import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { STUCK_PUBLISHING_MINUTES } from "../monitoring/thresholds.ts";

export async function recoverStalePublishingRows(
  admin: SupabaseClient,
  staleMinutes = STUCK_PUBLISHING_MINUTES,
): Promise<number> {
  const { data, error } = await admin.rpc("recover_stale_publishing_rows", {
    p_stale_minutes: staleMinutes,
  });
  if (error) throw new Error(error.message);
  return Number(data ?? 0);
}

/** Grace after scheduled_at before counting as late (1-min cron + buffer). */
export const PENDING_LATE_GRACE_MINUTES = 3;

/** Max time in publishing before counting as stuck (video upload). */
export const STUCK_PUBLISHING_MINUTES = 20;

/** Window for recent failures in monitoring. */
export const FAILED_MONITORING_HOURS = 24;

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { SchedulerConfig } from "../config/schedulerConfigTypes.ts";
import type { ScheduleMonitoringSummary } from "./queries.ts";

export type TickLogInput = {
  startedAt: Date;
  finishedAt: Date;
  durationMs: number;
  dryRun: boolean;
  claimed: number;
  resumed: number;
  processed: number;
  publishedOk: number;
  deferredRateLimited: number;
  failed: number;
  recoveredStale: number;
  monitoring: ScheduleMonitoringSummary;
  config: SchedulerConfig;
};

export async function insertTickLog(
  admin: SupabaseClient,
  input: TickLogInput,
): Promise<void> {
  const { error } = await admin.from("social_media_scheduler_tick_logs").insert({
    started_at: input.startedAt.toISOString(),
    finished_at: input.finishedAt.toISOString(),
    duration_ms: input.durationMs,
    dry_run: input.dryRun,
    claimed: input.claimed,
    resumed: input.resumed,
    processed: input.processed,
    published_ok: input.publishedOk,
    deferred_rate_limited: input.deferredRateLimited,
    failed: input.failed,
    recovered_stale: input.recoveredStale,
    pending_due_now: input.monitoring.pending_due_now_count,
    pending_late: input.monitoring.pending_late_count,
    rate_deferred: input.monitoring.rate_deferred_count,
    config_snapshot: input.config,
  });

  if (error) {
    console.warn("insertTickLog failed:", error.message);
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  FAILED_MONITORING_HOURS,
  PENDING_LATE_GRACE_MINUTES,
  STUCK_PUBLISHING_MINUTES,
} from "./thresholds.ts";

export type ScheduleMonitoringSummary = {
  pending_late_count: number;
  stuck_publishing_count: number;
  failed_24h_count: number;
  rate_deferred_count: number;
  pending_due_now_count: number;
};

function minutesAgoIso(minutes: number): string {
  return new Date(Date.now() - minutes * 60_000).toISOString();
}

function hoursAgoIso(hours: number): string {
  return new Date(Date.now() - hours * 3_600_000).toISOString();
}

async function fetchMonitoringSummaryFallback(
  admin: SupabaseClient,
): Promise<ScheduleMonitoringSummary> {
  const pendingLateBefore = minutesAgoIso(PENDING_LATE_GRACE_MINUTES);
  const stuckPublishingBefore = minutesAgoIso(STUCK_PUBLISHING_MINUTES);
  const failedSince = hoursAgoIso(FAILED_MONITORING_HOURS);

  const [pendingLate, stuckPublishing, failed24h] = await Promise.all([
    admin
      .from("social_media_scheduled_posts")
      .select("id", { count: "exact", head: true })
      .eq("status", "pending")
      .lt("scheduled_at", pendingLateBefore),
    admin
      .from("social_media_scheduled_posts")
      .select("id", { count: "exact", head: true })
      .eq("status", "publishing")
      .lt("updated_at", stuckPublishingBefore),
    admin
      .from("social_media_scheduled_posts")
      .select("id", { count: "exact", head: true })
      .eq("status", "failed")
      .gte("updated_at", failedSince),
  ]);

  return {
    pending_late_count: pendingLate.count ?? 0,
    stuck_publishing_count: stuckPublishing.count ?? 0,
    failed_24h_count: failed24h.count ?? 0,
    rate_deferred_count: 0,
    pending_due_now_count: 0,
  };
}

export async function fetchScheduleMonitoringSummary(
  admin: SupabaseClient,
): Promise<ScheduleMonitoringSummary> {
  const { data, error } = await admin.rpc("get_social_media_schedule_monitoring_summary");
  if (error || !data || typeof data !== "object") {
    console.warn("fetchScheduleMonitoringSummary rpc fallback:", error?.message);
    return fetchMonitoringSummaryFallback(admin);
  }

  const row = data as Record<string, unknown>;
  const summary: ScheduleMonitoringSummary = {
    pending_late_count: Number(row.pending_late_count ?? 0),
    stuck_publishing_count: Number(row.stuck_publishing_count ?? 0),
    failed_24h_count: Number(row.failed_24h_count ?? 0),
    rate_deferred_count: Number(row.rate_deferred_count ?? 0),
    pending_due_now_count: Number(row.pending_due_now_count ?? 0),
  };

  if (
    summary.pending_late_count > 0 ||
    summary.stuck_publishing_count > 0 ||
    summary.failed_24h_count > 0 ||
    summary.rate_deferred_count > 0
  ) {
    console.warn("social-media-scheduler monitoring:", JSON.stringify(summary));
  }

  return summary;
}

export async function runWithConcurrency<T, R>(
  items: T[],
  concurrency: number,
  worker: (item: T) => Promise<R>,
): Promise<R[]> {
  if (items.length === 0) return [];

  const limit = Math.max(1, Math.min(concurrency, items.length));
  const results: R[] = new Array(items.length);
  let nextIndex = 0;

  async function runWorker(): Promise<void> {
    for (;;) {
      const index = nextIndex;
      nextIndex += 1;
      if (index >= items.length) return;
      results[index] = await worker(items[index]);
    }
  }

  await Promise.all(Array.from({ length: limit }, () => runWorker()));
  return results;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { DEFAULT_MAX_PER_ORG_WINDOW } from "./rateLimitConfig.ts";

const orgMaxCache = new Map<string, number>();

export function clearOrgRateLimitCache(): void {
  orgMaxCache.clear();
}

async function resolveOrgMaxPerWindow(
  admin: SupabaseClient,
  organizationId: string,
): Promise<number> {
  const cached = orgMaxCache.get(organizationId);
  if (cached !== undefined) return cached;

  const { data, error } = await admin
    .from("organization_social_media_scheduling_settings")
    .select("max_publishes_per_5min")
    .eq("organization_id", organizationId)
    .maybeSingle();

  if (error) throw new Error(error.message);

  const max = Math.min(
    20,
    Math.max(1, Number(data?.max_publishes_per_5min ?? DEFAULT_MAX_PER_ORG_WINDOW)),
  );
  orgMaxCache.set(organizationId, max);
  return max;
}

export async function acquirePublishSlot(
  admin: SupabaseClient,
  organizationId: string,
  platform: string,
): Promise<boolean> {
  const maxPerWindow = await resolveOrgMaxPerWindow(admin, organizationId);
  const { data, error } = await admin.rpc("try_acquire_social_media_publish_slot", {
    p_organization_id: organizationId,
    p_platform: platform,
    p_max_per_window: maxPerWindow,
  });

  if (error) throw new Error(error.message);
  return Boolean(data);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { executeScheduledPost } from "./executeScheduledPost.ts";
import type { SchedulerConfig } from "./config/schedulerConfigTypes.ts";
import { DEFAULT_SCHEDULER_CONFIG } from "./config/schedulerConfigTypes.ts";
