  stripPublishResumeFlags,
} from "./rateLimit/deferForRateLimit.ts";
import {
  computeNextRetryAt,
  isInternalRateLimitMessage,
  resolveScheduleStatusAfterFailure,
} from "./scheduledPostRetry.ts";
import type { ScheduledPostRow } from "./scheduledPostTypes.ts";

export type RunScheduledPostJobResult = {
  id: string;
  ok: boolean;
  platform: string;
  error?: string;
  stubCode?: "manual_only" | "not_implemented";
  published_url?: string;
  external_post_id?: string;
  retry_count?: number;
  skipped?: "already_published" | "already_claimed";
  deferred?: "rate_limit" | "rate_limit_global";
};

export type RunScheduledPostJobOptions = {
  /** Row already transitioned to publishing by claim RPC. */
  fromClaim?: boolean;
  /** post_now: row inserted as publishing. */
  skipPublishingTransition?: boolean;
  preloadedRow?: ScheduledPostRow;
  schedulerConfig?: SchedulerConfig;
};


async function enforcePublishRateLimits(
  admin: SupabaseClient,
  row: ScheduledPostRow,
  schedulerConfig: SchedulerConfig,
): Promise<
  | { allowed: true }
  | { allowed: false; deferred: "rate_limit" | "rate_limit_global"; reason: string }
> {
  if (shouldDryRunPublish(row)) {
    return { allowed: true };
  }

  const providerConfig = row.provider_config ?? {};
  const isResume = isPublishResumeRow(row.platform, providerConfig);
  const globalCap = globalInFlightCapForPlatform(row.platform, schedulerConfig);

  if (globalCap !== null) {
    const inFlight = await countGlobalInFlightPublishing(admin, row.platform);
    if (inFlight > globalCap) {
      const reason = "rate_limited:global";
      await deferForRateLimit(admin, row.id, reason);
      return { allowed: false, deferred: "rate_limit_global", reason };
    }
  }

  if (!isResume) {
    const acquired = await acquirePublishSlot(admin, row.organization_id, row.platform);
    if (!acquired) {
      const reason = "rate_limited:org";
      await deferForRateLimit(admin, row.id, reason);
      return { allowed: false, deferred: "rate_limit", reason };
    }
  }

  return { allowed: true };
}

export async function runScheduledPostJob(
  admin: SupabaseClient,
  scheduleId: string,
  options?: RunScheduledPostJobOptions,
): Promise<RunScheduledPostJobResult> {
  let row: ScheduledPostRow | null = options?.preloadedRow ?? null;

  if (!row) {
    const { data: schedule, error: schedErr } = await admin
      .from("social_media_scheduled_posts")
      .select("*")
      .eq("id", scheduleId)
      .maybeSingle();

    if (schedErr || !schedule) {
      return { id: scheduleId, ok: false, platform: "unknown", error: "Schedule not found" };
    }
    row = schedule as ScheduledPostRow;
  }

  const platform = row.platform;

  if (row.status === "published" || row.external_post_id) {
    return {
      id: scheduleId,
      ok: true,
      platform,
      published_url: row.published_url ?? undefined,
      external_post_id: row.external_post_id,
      skipped: "already_published",
    };
  }

  if (row.status !== "pending" && row.status !== "publishing") {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: `Schedule not runnable (${row.status})`,
    };
  }

  if (options?.fromClaim) {
    if (row.status !== "publishing") {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "Claimed row not in publishing state",
      };
    }
  } else if (options?.skipPublishingTransition) {
    if (row.status !== "publishing") {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "post_now row must be publishing",
      };
    }
  } else if (row.status === "publishing") {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: "already_claimed",
      skipped: "already_claimed",
    };
  } else {
    const now = new Date().toISOString();
    const { data: locked, error: lockErr } = await admin
      .from("social_media_scheduled_posts")
      .update({
        status: "publishing",
        locked_at: now,
        updated_at: now,
      })
      .eq("id", scheduleId)
      .eq("status", "pending")
      .select("*")
      .maybeSingle();

    if (lockErr) {
      return { id: scheduleId, ok: false, platform, error: lockErr.message };
    }
    if (!locked) {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "already_claimed",
        skipped: "already_claimed",
      };
    }
    row = locked as ScheduledPostRow;
  }

  const schedulerConfig = options?.schedulerConfig ?? DEFAULT_SCHEDULER_CONFIG;

  const rateLimit = await enforcePublishRateLimits(admin, row, schedulerConfig);
  if (!rateLimit.allowed) {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: rateLimit.reason,
      deferred: rateLimit.deferred,
    };
  }

  try {
    const result = await executeScheduledPost(admin, row);
    const cleanedConfig = stripPublishResumeFlags(platform, row.provider_config ?? {});
    await admin
      .from("social_media_scheduled_posts")
      .update({
        status: "published",
        published_url: result.published_url,
        external_post_id: result.external_post_id,
        published_at: new Date().toISOString(),
        error_message: null,
        next_retry_at: null,
        locked_at: null,
        last_error_at: null,
        provider_config: cleanedConfig,
        updated_at: new Date().toISOString(),
      })
      .eq("id", scheduleId);

    return {
      id: scheduleId,
      ok: true,
      platform,
      published_url: result.published_url,
      external_post_id: result.external_post_id,
    };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "publish_failed";
    const stub = parseScheduleStubError(msg);
    const retryCount = isInternalRateLimitMessage(msg)
      ? Number(row.retry_count ?? 0)
      : Number(row.retry_count ?? 0) + 1;
    const nextStatus = stub || isScheduleStubError(msg)
      ? "failed"
      : resolveScheduleStatusAfterFailure(retryCount, msg, platform);
    const nextRetryAt = nextStatus === "pending"
      ? computeNextRetryAt(retryCount, msg, platform)
      : null;
    const now = new Date().toISOString();

    await admin
      .from("social_media_scheduled_posts")
      .update({
        status: nextStatus,
        error_message: msg,
        retry_count: retryCount,
        next_retry_at: nextRetryAt,
        last_error_at: now,
        locked_at: null,
        updated_at: now,
      })
      .eq("id", scheduleId);

    return {
      id: scheduleId,
      ok: false,
      platform,
      error: msg,
      stubCode: stub?.stubCode,
      retry_count: retryCount,
    };
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { shouldDryRunPublish } from "./dryRun/shouldDryRunPublish.ts";
import { executeDryRunScheduledPost } from "./executeDryRunScheduledPost.ts";
import {
  getPlatformScheduleCapability,
  normalizeSchedulePlatform,
} from "./platformRegistry.ts";
import { buildScheduleStubError } from "./platforms/stubErrors.ts";
import { executeTikTokScheduledPost } from "./platforms/tiktok.ts";
import { executeInstagramScheduledPost } from "./platforms/instagram.ts";
import { executeFacebookScheduledPost } from "./platforms/facebook.ts";
import { executeYouTubeScheduledPost } from "./platforms/youtube.ts";
import { executeLinkedInScheduledPost } from "./platforms/linkedin.ts";
import type { ScheduledPostRow } from "./scheduledPostTypes.ts";

export type ExecuteScheduledPostResult = {
  published_url: string;
  external_post_id: string;
};

export async function executeScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
): Promise<ExecuteScheduledPostResult> {
  const platform = normalizeSchedulePlatform(schedule.platform);
  const capability = getPlatformScheduleCapability(platform);

  if (!capability) {
    throw new Error(
      buildScheduleStubError("not_implemented", platform, schedule.delivery_mode ?? "unknown"),
    );
  }

  if (!capability.implemented) {
    throw new Error(
      buildScheduleStubError(capability.stubCode, platform, capability.deliveryMode),
    );
  }

  if (shouldDryRunPublish(schedule)) {
    return executeDryRunScheduledPost(schedule);
  }

  switch (platform) {
    case "TikTok":
      return executeTikTokScheduledPost(admin, schedule);
    case "Instagram":
      return executeInstagramScheduledPost(admin, schedule);
    case "Facebook":
      return executeFacebookScheduledPost(admin, schedule);
    case "YouTube":
      return executeYouTubeScheduledPost(admin, schedule);
    case "LinkedIn":
      return executeLinkedInScheduledPost(admin, schedule);
    default:
      throw new Error(
        buildScheduleStubError("not_implemented", platform, schedule.delivery_mode ?? "unknown"),
      );
  }
}

import { isSchedulerDryRunEnvEnabled } from "../config/loadSchedulerConfig.ts";
import type { ScheduledPostRow } from "../scheduledPostTypes.ts";

export function isLoadTestScheduleRow(schedule: ScheduledPostRow): boolean {
  const providerConfig = schedule.provider_config ?? {};
  if (providerConfig.load_test === true || providerConfig.load_test === "true") {
    return true;
  }
  const snapshot = String(schedule.media_url_snapshot ?? "");
  return snapshot.startsWith("load-test://");
}

export function shouldDryRunPublish(schedule: ScheduledPostRow): boolean {
  if (!isSchedulerDryRunEnvEnabled()) return false;
  return isLoadTestScheduleRow(schedule);
}

import { sleepMs } from "./scheduledPostRetry.ts";
import type { ScheduledPostRow } from "./scheduledPostTypes.ts";

function dryRunLatencyMs(): number {
  const base = parseInt(Deno.env.get("SCHEDULER_DRY_RUN_LATENCY_MS") ?? "3000", 10);
  const jitter = Math.floor(Math.random() * 2001) - 1000;
  return Math.max(500, (Number.isFinite(base) ? base : 3000) + jitter);
}

export async function executeDryRunScheduledPost(
  schedule: ScheduledPostRow,
): Promise<{ published_url: string; external_post_id: string }> {
  await sleepMs(dryRunLatencyMs());
  const suffix = crypto.randomUUID().slice(0, 8);
  return {
    published_url: `dry-run://${schedule.platform.toLowerCase()}/${schedule.id}/${suffix}`,
    external_post_id: `dry_run_${suffix}`,
  };
}

export function isInternalRateLimitMessage(message: string): boolean {
  return message.startsWith("rate_limited:");
}

export function parseRetryAfterSeconds(message: string): number | null {
  const match = message.match(/retry-after:(\d+)/i);
  if (!match) return null;
  const seconds = parseInt(match[1], 10);
  return Number.isFinite(seconds) && seconds > 0 ? seconds : null;
}

/** ISO timestamp after TikTok HTTP 429 Retry-After (clamped 60s–15m). */
export function computeNextRetryAtFrom429(retryAfterSeconds?: number): string {
  const seconds = Math.min(900, Math.max(60, retryAfterSeconds ?? 120));
  return new Date(Date.now() + seconds * 1000).toISOString();
}

/** Transient TikTok / network errors — keep schedule pending and retry via cron. */
export function isTransientScheduledPublishError(message: string): boolean {
  const m = message.toLowerCase();
  return (
    /\bhttp\s*503\b/.test(m) ||
    /\bhttp\s*502\b/.test(m) ||
    /\bhttp\s*504\b/.test(m) ||
    /\bhttp\s*429\b/.test(m) ||
    m.includes("publish_timeout") ||
    m.includes("econnreset") ||
    m.includes("network error")
  );
}

export function isTransientYouTubePublishError(message: string): boolean {
  const m = message.toLowerCase();
  return (
    isTransientScheduledPublishError(message) ||
    m.includes("quotaexceeded") ||
    m.includes("uploadtimeout") ||
    m.includes("processing_timeout") ||
    m.includes("backenderror")
  );
}

export function isTransientMetaPublishError(message: string): boolean {
  const m = message.toLowerCase();
  return (
    isTransientScheduledPublishError(message) ||
    m.includes("application request limit") ||
    m.includes("(#4)") ||
    m.includes("(#613)") ||
    m.includes("media_not_ready") ||
    m.includes("transient")
  );
}

export function isTransientLinkedInPublishError(message: string): boolean {
  const m = message.toLowerCase();
  return (
    isTransientScheduledPublishError(message) ||
    m.includes("throttle") ||
    m.includes("rate limit") ||
    m.includes("service unavailable")
  );
}

export function isTransientPublishErrorForPlatform(platform: string, message: string): boolean {
  switch (platform.trim()) {
    case "TikTok":
      return isTransientScheduledPublishError(message);
    case "YouTube":
      return isTransientYouTubePublishError(message);
    case "Instagram":
      return isTransientMetaPublishError(message);
    case "LinkedIn":
      return isTransientLinkedInPublishError(message);
    default:
      return isTransientScheduledPublishError(message);
  }
}

export const SCHEDULED_POST_MAX_RETRIES_TRANSIENT = 8;
export const SCHEDULED_POST_MAX_RETRIES_DEFAULT = 2;

const RETRY_BACKOFF_MINUTES = [2, 5, 15, 30, 60] as const;

export function resolveScheduleStatusAfterFailure(
  retryCount: number,
  errorMessage: string,
  platform?: string,
): "pending" | "failed" {
  const max = isTransientPublishErrorForPlatform(platform ?? "TikTok", errorMessage)
    ? SCHEDULED_POST_MAX_RETRIES_TRANSIENT
    : SCHEDULED_POST_MAX_RETRIES_DEFAULT;
  return retryCount >= max ? "failed" : "pending";
}

/** ISO timestamp for next claim attempt; null when row should stay failed. */
export function computeNextRetryAt(
  retryCount: number,
  errorMessage: string,
  platform?: string,
): string | null {
  const nextStatus = resolveScheduleStatusAfterFailure(retryCount, errorMessage, platform);
  if (nextStatus === "failed") return null;

  const retryAfterSeconds = parseRetryAfterSeconds(errorMessage);
  if (retryAfterSeconds !== null) {
    return computeNextRetryAtFrom429(retryAfterSeconds);
  }

  const idx = Math.min(Math.max(retryCount, 1), RETRY_BACKOFF_MINUTES.length) - 1;
  const minutes = RETRY_BACKOFF_MINUTES[idx] ?? 60;
  return new Date(Date.now() + minutes * 60_000).toISOString();
}

export function sleepMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export type PlatformStubCode = "manual_only" | "not_implemented";

export type PlatformScheduleCapability =
  | { deliveryMode: "api_auto"; implemented: true }
  | { deliveryMode: "manual_only"; implemented: false; stubCode: "manual_only" }
  | { deliveryMode: "api_auto"; implemented: false; stubCode: "not_implemented" };

export const PLATFORM_SCHEDULE_REGISTRY: Record<string, PlatformScheduleCapability> = {
  TikTok: { deliveryMode: "api_auto", implemented: true },
  Instagram: { deliveryMode: "api_auto", implemented: true },
  Facebook: { deliveryMode: "api_auto", implemented: true },
  YouTube: { deliveryMode: "api_auto", implemented: true },
  LinkedIn: { deliveryMode: "api_auto", implemented: true },
};

export function normalizeSchedulePlatform(platform: string): string {
  return platform.trim();
}

export function getPlatformScheduleCapability(platform: string): PlatformScheduleCapability | null {
  const key = normalizeSchedulePlatform(platform);
  return PLATFORM_SCHEDULE_REGISTRY[key] ?? null;
}

export function assertPlatformCanSchedule(platform: string): void {
  const capability = getPlatformScheduleCapability(platform);
  if (!capability) {
    throw new Error(`schedule_stub:not_implemented:${normalizeSchedulePlatform(platform)}:Unknown platform`);
  }
  if (!capability.implemented) {
    throw new Error(
      `schedule_stub:${capability.stubCode}:${normalizeSchedulePlatform(platform)}:${capability.deliveryMode}`,
    );
  }
}

import type { PlatformStubCode } from "../platformRegistry.ts";

const STUB_MESSAGES: Record<PlatformStubCode, string> = {
  manual_only:
    "Auto-schedule is not available for this platform. Add the post link manually in the publish modal.",
  not_implemented:
    "API auto-publish for this platform is not implemented yet.",
};

export function buildScheduleStubError(
  stubCode: PlatformStubCode,
  platform: string,
  deliveryMode: string,
): string {
  const base = STUB_MESSAGES[stubCode];
  return `schedule_stub:${stubCode}:${platform}:${deliveryMode} — ${base}`;
}

export function isScheduleStubError(message: string): boolean {
  return message.startsWith("schedule_stub:");
}

export function parseScheduleStubError(
  message: string,
): { stubCode: PlatformStubCode; platform: string } | null {
  if (!isScheduleStubError(message)) return null;
  const parts = message.split(":");
  if (parts.length < 3) return null;
  const stubCode = parts[1] as PlatformStubCode;
  const platform = parts[2];
  if (stubCode !== "manual_only" && stubCode !== "not_implemented") return null;
  return { stubCode, platform };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { tiktokContentScopesIncludePublish } from "../tiktokContentAuth.ts";
import { getTikTokPublishAccessToken } from "../tiktokContentOrgResolver.ts";
import {
  computeTikTokFileUploadChunkPlan,
  deriveTikTokPostInteractionFromCreator,
  initTikTokVideoPublishFileUpload,
  pollTikTokPublishUntilComplete,
  queryTikTokCreatorInfo,
  resolveTikTokPublishPrivacyLevel,
  uploadTikTokVideoChunks,
} from "../tiktokContent/tiktokContentPublishApi.ts";
import { downloadGoogleDriveVideo } from "../scheduledPosts/googleDriveVideoDownload.ts";
import {
  isPlanEligibleForTikTokAutoSchedule,
  shouldCancelScheduleDueToDriveMismatch,
} from "../scheduledPosts/scheduledPostEligibility.ts";
import { syncPlanCompletionStateForPlan } from "../scheduledPosts/syncPlanCompletionStateDb.ts";
import type { ScheduledPostRow } from "../scheduledPosts/scheduledPostTypes.ts";
import { DEFAULT_PRIVACY_LEVEL } from "../scheduledPosts/scheduledPostTypes.ts";

type PlanRow = {
  id: string;
  organization_id: string;
  post_date: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  post_link_created_by: string | null;
  content_type?: { name?: string } | null;
};

type TikTokProviderConfigExt = {
  open_id?: string;
  account_label?: string;
  employee_id?: string;
  tiktok_publish_id?: string;
  tiktok_upload_completed?: boolean;
};

async function loadPlan(admin: SupabaseClient, planId: string): Promise<PlanRow | null> {
  const { data, error } = await admin
    .from("social_media_plans")
    .select(
      "id, organization_id, post_date, approved, production_approved, google_drive_link, post_link_created_by, content_type:content_types(name)",
    )
    .eq("id", planId)
    .maybeSingle();
  if (error || !data) return null;
  return data as PlanRow;
}

function planEligibilityInput(plan: PlanRow) {
  return {
    post_date: plan.post_date,
    approved: plan.approved,
    production_approved: plan.production_approved,
    google_drive_link: plan.google_drive_link,
    content_type_name: plan.content_type?.name ?? null,
  };
}

async function persistTikTokProviderConfig(
  admin: SupabaseClient,
  scheduleId: string,
  base: Record<string, unknown>,
  patch: Partial<TikTokProviderConfigExt>,
): Promise<Record<string, unknown>> {
  const next = { ...base, ...patch };
  await admin
    .from("social_media_scheduled_posts")
    .update({
      provider_config: next,
      updated_at: new Date().toISOString(),
    })
    .eq("id", scheduleId);
  return next;
}

async function upsertTikTokLink(
  admin: SupabaseClient,
  plan: PlanRow,
  args: {
    url: string;
    openId: string;
    accountLabel: string;
    externalPostId: string | null;
    scheduledBy: string | null;
    employeeId?: string;
  },
): Promise<void> {
  const { data: existing } = await admin
    .from("social_media_links")
    .select("id")
    .eq("social_media_plan_id", plan.id)
    .eq("platform", "TikTok")
    .maybeSingle();

  const payload = {
    platform: "TikTok",
    url: args.url,
    social_media_name: args.accountLabel,
    external_post_id: args.externalPostId,
    platform_account_open_id: args.openId,
    updated_at: new Date().toISOString(),
  };

  if (existing?.id) {
    await admin.from("social_media_links").update(payload).eq("id", existing.id);
  } else {
    await admin.from("social_media_links").insert({
      ...payload,
      social_media_plan_id: plan.id,
    });

    if (!plan.post_link_created_by) {
      const employeeId = String(args.employeeId ?? "").trim();
      if (employeeId) {
        await admin
          .from("social_media_plans")
          .update({ post_link_created_by: employeeId })
          .eq("id", plan.id);
      }
    }
  }

  await syncPlanCompletionStateForPlan(admin, plan.id);
}

async function finalizeTikTokPublish(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
  plan: PlanRow,
  openId: string,
  publishAccessToken: string,
  externalPostId: string,
  creatorUsername?: string,
): Promise<{ published_url: string; external_post_id: string }> {
  const cfg = schedule.provider_config as TikTokProviderConfigExt;
  const { data: account } = await admin
    .from("organization_tiktok_content_accounts")
    .select("label, display_name")
    .eq("organization_id", schedule.organization_id)
    .eq("open_id", openId)
    .maybeSingle();

  const accountLabel = String(
    cfg.account_label ?? account?.display_name ?? account?.label ?? "TikTok",
  );

  let publishedUrl =
    `https://www.tiktok.com/@${creatorUsername ?? "user"}/video/${externalPostId}`;
  if (externalPostId && !publishedUrl.includes(externalPostId)) {
    publishedUrl = `https://www.tiktok.com/video/${externalPostId}`;
  }

  await upsertTikTokLink(admin, plan, {
    url: publishedUrl,
    openId,
    accountLabel,
    externalPostId,
    scheduledBy: schedule.scheduled_by,
    employeeId: cfg.employee_id,
  });

  return { published_url: publishedUrl, external_post_id: externalPostId };
}

export async function executeTikTokScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const plan = await loadPlan(admin, schedule.social_media_plan_id);
  if (!plan) throw new Error("plan_not_found");

  if (!isPlanEligibleForTikTokAutoSchedule(planEligibilityInput(plan))) {
    throw new Error("plan_not_eligible");
  }

  if (shouldCancelScheduleDueToDriveMismatch(schedule.media_url_snapshot, plan.google_drive_link)) {
    throw new Error("google_drive_link_changed");
  }

  const cfg = schedule.provider_config as TikTokProviderConfigExt;
  const openId = String(cfg.open_id ?? "").trim();
  if (!openId) throw new Error("missing_open_id");

  const publishAccessToken = await getTikTokPublishAccessToken(
    admin,
    schedule.organization_id,
    openId,
  );
  if (!publishAccessToken) {
    throw new Error(
      "publish_login_kit_token_missing: Re-authorize TikTok publishing in Digital Marketing settings",
    );
  }

  const scopes = await admin
    .from("organization_tiktok_content_connection_tokens")
    .select("oauth_scopes, publish_oauth_scopes")
    .eq("organization_id", schedule.organization_id)
    .eq("open_id", openId)
    .maybeSingle();

  const scopeForPublish = (scopes.data?.publish_oauth_scopes as string | null) ??
    (scopes.data?.oauth_scopes as string | null);
  if (!tiktokContentScopesIncludePublish(scopeForPublish)) {
    throw new Error("publish_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };

  if (cfg.tiktok_publish_id && cfg.tiktok_upload_completed) {
    const publishStatus = await pollTikTokPublishUntilComplete(
      publishAccessToken,
      cfg.tiktok_publish_id,
    );
    const postIds = publishStatus.publicaly_available_post_id ?? [];
    const externalPostId = postIds.length > 0
      ? String(postIds[0])
      : cfg.tiktok_publish_id;

    let creatorUsername: string | undefined;
    try {
      const creatorInfo = await queryTikTokCreatorInfo(publishAccessToken);
      creatorUsername = creatorInfo.creator_username;
    } catch {
      creatorUsername = undefined;
    }

    return finalizeTikTokPublish(
      admin,
      schedule,
      plan,
      openId,
      publishAccessToken,
      externalPostId,
      creatorUsername,
    );
  }

  if (cfg.tiktok_publish_id && !cfg.tiktok_upload_completed) {
    throw new Error("tiktok_upload_incomplete: wait for stale recovery or retry");
  }

  const driveUrl = plan.google_drive_link?.trim() ?? schedule.media_url_snapshot;
  const { bytes: videoBytes, mimeType } = await downloadGoogleDriveVideo(driveUrl);

  const creatorInfo = await queryTikTokCreatorInfo(publishAccessToken);
  const privacyLevel = resolveTikTokPublishPrivacyLevel(
    schedule.privacy_level ?? DEFAULT_PRIVACY_LEVEL,
    creatorInfo,
  );

  const caption = schedule.caption?.trim() || schedule.title?.trim() || " ";
  const chunkPlan = computeTikTokFileUploadChunkPlan(videoBytes.byteLength);
  const interaction = deriveTikTokPostInteractionFromCreator(creatorInfo);
  const initResult = await initTikTokVideoPublishFileUpload(publishAccessToken, {
    videoSize: videoBytes.byteLength,
    chunkSize: chunkPlan.chunkSize,
    totalChunkCount: chunkPlan.totalChunkCount,
    caption,
    privacyLevel,
    disableComment: interaction.disableComment,
    disableDuet: interaction.disableDuet,
    disableStitch: interaction.disableStitch,
  });

  providerConfig = await persistTikTokProviderConfig(admin, schedule.id, providerConfig, {
    tiktok_publish_id: initResult.publish_id,
    tiktok_upload_completed: false,
  });

  await uploadTikTokVideoChunks(
    String(initResult.upload_url),
    videoBytes,
    chunkPlan,
    mimeType,
  );

  providerConfig = await persistTikTokProviderConfig(admin, schedule.id, providerConfig, {
    tiktok_upload_completed: true,
  });

  const publishStatus = await pollTikTokPublishUntilComplete(
    publishAccessToken,
    initResult.publish_id,
  );

  const postIds = publishStatus.publicaly_available_post_id ?? [];
  const externalPostId = postIds.length > 0 ? String(postIds[0]) : initResult.publish_id;

  return finalizeTikTokPublish(
    admin,
    schedule,
    plan,
    openId,
    publishAccessToken,
    externalPostId,
    creatorInfo.creator_username,
  );
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_CONTENT_API_BASE = "https://open.tiktokapis.com/v2";
export const TIKTOK_BUSINESS_API_BASE = "https://business-api.tiktok.com/open_api/v1.3";
export const TIKTOK_CONTENT_OAUTH_SCOPES =
  "user.info.basic,video.list,user.info.stats,comment.list,comment.list.manage,video.upload,video.publish";

export const TIKTOK_CONTENT_PUBLISH_SCOPES = ["video.upload", "video.publish"] as const;

/** Login Kit / Direct Post (developers.tiktok.com) — separate from business-api CONTENT credentials. */
export const TIKTOK_CONTENT_PUBLISH_OAUTH_SCOPES =
  "user.info.basic,video.upload,video.publish";

export type TikTokContentOAuthTokenKind = "login_kit" | "tt_user";

export const TIKTOK_CONTENT_OAUTH_TOKEN_KINDS = {
  loginKit: "login_kit" as TikTokContentOAuthTokenKind,
  ttUser: "tt_user" as TikTokContentOAuthTokenKind,
};

export const TIKTOK_CONTENT_COMMENT_SCOPES = ["comment.list", "comment.list.manage"] as const;

/** Union comma-separated OAuth scope strings (deduped, stable order). */
export function mergeTikTokContentOAuthScopes(
  ...scopeStrings: (string | null | undefined)[]
): string {
  const merged = new Set<string>();
  for (const raw of scopeStrings) {
    for (const part of String(raw ?? "").split(",")) {
      const trimmed = part.trim();
      if (trimmed) merged.add(trimmed);
    }
  }
  return [...merged].join(",");
}

/** TikTok often omits scopes in token JSON; merge stored + requested scopes. */
export function resolveTikTokContentOAuthScopes(stored: string | null | undefined): string {
  return mergeTikTokContentOAuthScopes(stored, TIKTOK_CONTENT_OAUTH_SCOPES);
}

export function tiktokContentScopesIncludeComments(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_COMMENT_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentScopesIncludePublish(scope: string | null | undefined): boolean {
  const parts = String(scope ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  return TIKTOK_CONTENT_PUBLISH_SCOPES.every((required) => parts.includes(required));
}

export function tiktokContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformTikTokContentOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_CONTENT_APP_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

/** developers.tiktok.com app — Login Kit token exchange & publish OAuth start. */
export function readPlatformTikTokContentPublishOAuth(): { clientKey: string; clientSecret: string } | null {
  const clientKey = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_KEY")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_KEY")?.trim() ?? "";
  const clientSecret = Deno.env.get("TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_DEVELOPERS_CLIENT_SECRET")?.trim() ?? "";
  if (!clientKey || !clientSecret) return null;
  return { clientKey, clientSecret };
}

export function isTikTokContentPlatformConfigured(): boolean {
  return readPlatformTikTokContentOAuth() !== null;
}

export function isTikTokContentPublishPlatformConfigured(): boolean {
  return readPlatformTikTokContentPublishOAuth() !== null;
}

export function requireTikTokContentPlatformConfigured(): Response | null {
  if (!isTikTokContentPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok Content is not configured. Set TIKTOK_CONTENT_CLIENT_KEY and TIKTOK_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function requireTikTokContentPublishPlatformConfigured(): Response | null {
  if (!isTikTokContentPublishPlatformConfigured()) {
    return tiktokContentJson(
      {
        error:
          "TikTok publish is not configured. Set TIKTOK_CONTENT_PUBLISH_CLIENT_KEY and TIKTOK_CONTENT_PUBLISH_CLIENT_SECRET (developers.tiktok.com app) in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function tiktokContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("TIKTOK_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/tiktok-content-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
