  has_more: boolean;
} {
  const comments = (data.comments ?? [])
    .map((row) => normalizeCommentRow(row))
    .filter((c) => c.id);
  const cursor = data.cursor;
  return {
    comments,
    cursor: cursor != null && Number.isFinite(Number(cursor)) ? Number(cursor) : null,
    has_more: Boolean(data.has_more),
  };
}

