  },
): Promise<TikTokVideoInitResult> {
  const res = await fetch(`${TIKTOK_CONTENT_API_BASE}/post/publish/video/init/`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json; charset=UTF-8",
    },
    body: JSON.stringify({
      post_info: {
        title: args.caption.slice(0, 2200),
        privacy_level: args.privacyLevel,
        disable_comment: args.disableComment ?? false,
        disable_duet: args.disableDuet ?? false,
        disable_stitch: args.disableStitch ?? false,
        brand_content_toggle: false,
        brand_organic_toggle: false,
      },
      source_info: {
        source: "PULL_FROM_URL",
        video_url: args.videoUrl,
      },
    }),
  });
  const json = await res.json().catch(() => ({})) as TikTokContentEnvelope<TikTokVideoInitResult>;
  if (!res.ok || json.error?.code !== "ok" || !json.data?.publish_id) {
    throwPublishError("video_init_failed", json.error, res.status, res);
  }
  return json.data;
}

export type TikTokPublishStatus = {
  status: string;
  fail_reason?: string;
  publicaly_available_post_id?: string[];
  uploaded_bytes?: number;
};

export async function fetchTikTokPublishStatus(
  accessToken: string,
  publishId: string,
): Promise<TikTokPublishStatus> {
  const res = await fetch(`${TIKTOK_CONTENT_API_BASE}/post/publish/status/fetch/`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json; charset=UTF-8",
    },
    body: JSON.stringify({ publish_id: publishId }),
  });
  const json = await res.json().catch(() => ({})) as TikTokContentEnvelope<TikTokPublishStatus>;
  if (!res.ok || json.error?.code !== "ok") {
    throwPublishError("publish_status_failed", json.error, res.status, res);
  }
  return json.data ?? { status: "UNKNOWN" };
}

export async function pollTikTokPublishUntilComplete(
  accessToken: string,
  publishId: string,
  options?: { maxAttempts?: number; delayMs?: number },
): Promise<TikTokPublishStatus> {
  const maxAttempts = options?.maxAttempts ?? 30;
  const delayMs = options?.delayMs ?? 2000;

  for (let i = 0; i < maxAttempts; i++) {
    const status = await fetchTikTokPublishStatus(accessToken, publishId);
    const s = String(status.status ?? "").toUpperCase();
    if (s === "PUBLISH_COMPLETE") return status;
    if (s === "FAILED") {
      throw new Error(`publish_failed: ${status.fail_reason ?? "unknown"}`);
    }
    await new Promise((r) => setTimeout(r, delayMs));
  }
  throw new Error("publish_timeout: TikTok publish did not complete in time");
}

import { resolveGoogleDrivePublicVideoUrl } from "./googleDrivePublicVideoUrl.ts";

const MAX_VIDEO_BYTES = 128 * 1024 * 1024;

function normalizeVideoMimeType(contentType: string | null): string {
  const raw = String(contentType ?? "").split(";")[0].trim().toLowerCase();
  if (raw.startsWith("video/")) return raw;
  return "video/mp4";
}

function isHtmlResponse(contentType: string | null, bytes: Uint8Array): boolean {
  const type = String(contentType ?? "").toLowerCase();
  if (type.includes("text/html")) return true;
  const head = new TextDecoder().decode(bytes.subarray(0, Math.min(bytes.byteLength, 256))).toLowerCase();
  return head.includes("<!doctype html") || head.includes("<html");
}

/** Download a publicly shared Google Drive video for TikTok FILE_UPLOAD. */
export async function downloadGoogleDriveVideo(
  driveShareUrl: string,
): Promise<{ bytes: Uint8Array; mimeType: string }> {
  const downloadUrl = resolveGoogleDrivePublicVideoUrl(driveShareUrl);
  if (!downloadUrl) throw new Error("invalid_google_drive_video_url");

  const res = await fetch(downloadUrl, { redirect: "follow" });
  if (!res.ok) {
    throw new Error(`drive_download_failed: HTTP ${res.status}`);
  }

  const contentLength = Number(res.headers.get("content-length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > MAX_VIDEO_BYTES) {
    throw new Error(`drive_video_too_large: ${contentLength} bytes (max ${MAX_VIDEO_BYTES})`);
  }

  const bytes = new Uint8Array(await res.arrayBuffer());
  if (bytes.byteLength === 0) {
    throw new Error("drive_download_failed: empty file");
  }
  if (bytes.byteLength > MAX_VIDEO_BYTES) {
    throw new Error(`drive_video_too_large: ${bytes.byteLength} bytes (max ${MAX_VIDEO_BYTES})`);
  }

  const mimeType = normalizeVideoMimeType(res.headers.get("content-type"));
  if (isHtmlResponse(res.headers.get("content-type"), bytes)) {
    throw new Error(
      "drive_download_failed: Google Drive returned HTML instead of video. Ensure the file is shared as Anyone with the link can view.",
    );
  }

  return { bytes, mimeType };
}

/** Extract Google Drive file id from share URL. */
export function extractGoogleDriveFileId(url: string): string | null {
  if (!url?.trim()) return null;
  const fileMatch = url.match(/\/file\/d\/([a-zA-Z0-9-_]+)/i);
  if (fileMatch) return fileMatch[1];
  if (url.includes("drive.google.com") && /[?&]id=([a-zA-Z0-9-_]+)/i.test(url)) {
    const openMatch = url.match(/[?&]id=([a-zA-Z0-9-_]+)/i);
    if (openMatch) return openMatch[1];
  }
  return null;
}

export function isGoogleDriveFolderLink(url: string): boolean {
  return url.includes("drive.google.com/drive/folders/");
}

export function isGoogleDriveFileLink(url: string): boolean {
  if (!url?.trim()) return false;
  if (isGoogleDriveFolderLink(url)) return false;
  return extractGoogleDriveFileId(url) !== null;
}

/** Direct download URL for public Google Drive video (server-side fetch for TikTok FILE_UPLOAD). */
export function resolveGoogleDrivePublicVideoUrl(url: string): string | null {
  const fileId = extractGoogleDriveFileId(url);
  if (!fileId) return null;
  return `https://drive.usercontent.google.com/download?id=${fileId}&export=download&confirm=t`;
}

export function normalizeGoogleDriveUrl(url: string): string {
  const raw = url?.trim() ?? "";
  if (!raw) return "";
  const fileId = extractGoogleDriveFileId(raw);
  if (fileId && raw.toLowerCase().includes("drive.google.com")) {
    return `file:${fileId}`;
  }
  return raw.toLowerCase().split("?")[0].split("#")[0];
}

export function googleDriveLinksSemanticallyEqual(
  a: string | null | undefined,
  b: string | null | undefined,
): boolean {
  return normalizeGoogleDriveUrl(a ?? "") === normalizeGoogleDriveUrl(b ?? "");
}

import { googleDriveLinksSemanticallyEqual, isGoogleDriveFileLink } from "./googleDrivePublicVideoUrl.ts";

export type PlanEligibilityInput = {
  post_date: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  content_type_name: string | null;
};

export type PlanAutoScheduleEligibilityInput = PlanEligibilityInput & {
  service_id: string | null;
};

export function isReelContentType(contentTypeName: string | null | undefined): boolean {
  return String(contentTypeName ?? "").trim().toLowerCase() === "reel";
}

export function isPlanEligibleForTikTokAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForYouTubeAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForInstagramAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForFacebookAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForLinkedInAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForReelAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (!plan.post_date) return false;
  if (!plan.approved) return false;
  if (!plan.production_approved) return false;
  if (!isReelContentType(plan.content_type_name)) return false;
  const link = plan.google_drive_link?.trim() ?? "";
  if (!link) return false;
  if (!isGoogleDriveFileLink(link)) return false;
  return true;
}

export function isPlanEligibleForAutoSchedule(plan: PlanAutoScheduleEligibilityInput): boolean {
  if (!isPlanEligibleForReelAutoSchedule(plan)) return false;
  if (!String(plan.service_id ?? "").trim()) return false;
  return true;
}

export function getPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  const reasons: string[] = [];
  if (!plan.post_date) reasons.push("post_date");
  if (!isReelContentType(plan.content_type_name)) reasons.push("content_type_reel");
  if (!plan.approved) reasons.push("approved");
  if (!plan.production_approved) reasons.push("production_approved");
  const link = plan.google_drive_link?.trim() ?? "";
  if (!link) reasons.push("google_drive_link");
  else if (!isGoogleDriveFileLink(link)) reasons.push("google_drive_file");
  return reasons;
}

export function shouldCancelScheduleDueToDriveMismatch(
  snapshot: string,
  currentLink: string | null | undefined,
): boolean {
  return !googleDriveLinksSemanticallyEqual(snapshot, currentLink);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { ScheduleRow } from "./pickPlatformScheduleServer.ts";
import {
  computePlanDoneState,
  computeRequiredPlatformProgressItems,
  derivePlanPostMetadata,
  filterRequiredPlatformsForContentType,
  type RequiredPlatformRow,
  type SocialMediaLinkRow,
} from "./syncPlanDoneState.ts";
import { calculateOnTimeStatus } from "./syncPlanPostMetadata.ts";

export type SyncPlanCompletionResult = {
  done: boolean | null;
  actual_post_date: string | null;
  on_time_status: string;
};

async function loadPlanCompletionInputs(
  admin: SupabaseClient,
  planId: string,
): Promise<{
  plan: {
    id: string;
    service_id: string | null;
    done: boolean;
    post_date: string | null;
    actual_post_date: string | null;
    on_time_status: string | null;
    contentTypeName: string | null;
  };
  required: RequiredPlatformRow[];
  links: SocialMediaLinkRow[];
  schedules: ScheduleRow[];
} | null> {
  const { data: plan, error: planErr } = await admin
    .from("social_media_plans")
    .select("id, service_id, done, post_date, actual_post_date, on_time_status, content_type:content_types(name)")
    .eq("id", planId)
    .maybeSingle();

  if (planErr || !plan) {
    console.error("syncPlanCompletionStateForPlan plan:", planErr?.message);
    return null;
  }

  const contentTypeName = (plan as { content_type?: { name?: string } }).content_type?.name ?? null;
  const serviceId = (plan as { service_id?: string | null }).service_id;

  let required: RequiredPlatformRow[] = [];
  if (serviceId) {
    const { data: reqRows } = await admin
      .from("service_required_platforms")
      .select("id, platform, is_active, platform_account_id, platform_account_label, custom_platform_name")
      .eq("service_id", serviceId)
      .eq("is_active", true);
    required = (reqRows ?? []) as RequiredPlatformRow[];
  }

  const { data: links } = await admin
    .from("social_media_links")
    .select("platform, url, platform_account_open_id, created_at")
    .eq("social_media_plan_id", planId);

  const { data: scheduleRows } = await admin
    .from("social_media_scheduled_posts")
    .select("id, platform, status, created_at, published_at, provider_config, platform_account_id")
    .eq("social_media_plan_id", planId);

  return {
    plan: {
      id: String(plan.id),
      service_id: serviceId,
      done: Boolean((plan as { done?: boolean }).done),
      post_date: (plan as { post_date?: string | null }).post_date ?? null,
      actual_post_date: (plan as { actual_post_date?: string | null }).actual_post_date ?? null,
      on_time_status: (plan as { on_time_status?: string | null }).on_time_status ?? null,
      contentTypeName,
    },
    required,
    links: (links ?? []) as SocialMediaLinkRow[],
    schedules: (scheduleRows ?? []) as ScheduleRow[],
  };
}

export async function syncPlanCompletionStateForPlan(
  admin: SupabaseClient,
  planId: string,
): Promise<SyncPlanCompletionResult | null> {
  const inputs = await loadPlanCompletionInputs(admin, planId);
  if (!inputs) return null;

  const { plan, required, links, schedules } = inputs;
  const activeRequired = filterRequiredPlatformsForContentType(required, plan.contentTypeName);
  const hasRequiredPlatforms = activeRequired.length > 0;

  const done = computePlanDoneState(required, links, plan.contentTypeName, schedules);
  const items = computeRequiredPlatformProgressItems(
    required,
    links,
    plan.contentTypeName,
    schedules,
  );
  const metadata = derivePlanPostMetadata(
    items,
    links,
    plan.post_date,
    hasRequiredPlatforms,
    calculateOnTimeStatus,
  );

  const currentOnTime = String(plan.on_time_status ?? "").trim();
  const needsUpdate =
    plan.done !== done
    || plan.actual_post_date !== metadata.actual_post_date
    || currentOnTime !== metadata.on_time_status;

  if (!needsUpdate) {
    return { done, ...metadata };
  }

  const { error: updateErr } = await admin
    .from("social_media_plans")
    .update({
      done,
      actual_post_date: metadata.actual_post_date,
      on_time_status: metadata.on_time_status,
      updated_at: new Date().toISOString(),
    })
    .eq("id", planId);

  if (updateErr) {
    console.error("syncPlanCompletionStateForPlan update:", updateErr.message);
    return null;
  }

  return { done, ...metadata };
}

/** @deprecated Use syncPlanCompletionStateForPlan */
export async function syncPlanDoneStateForPlan(
  admin: SupabaseClient,
  planId: string,
): Promise<boolean | null> {
  const result = await syncPlanCompletionStateForPlan(admin, planId);
  return result?.done ?? null;
}

/** @deprecated Use syncPlanCompletionStateForPlan */
export async function syncPlanPostMetadataForPlan(
  admin: SupabaseClient,
  planId: string,
): Promise<{ actual_post_date: string | null; on_time_status: string } | null> {
  const result = await syncPlanCompletionStateForPlan(admin, planId);
  if (!result) return null;
  return {
    actual_post_date: result.actual_post_date,
    on_time_status: result.on_time_status,
  };
}

export type ScheduleRow = {
  id: string;
  platform: string;
  status: string;
  created_at: string;
  published_at: string | null;
  provider_config: Record<string, unknown> | null;
  platform_account_id?: string | null;
};

const ACTIVE_STATUSES = new Set(["pending", "publishing"]);

export function getAccountIdFromProviderConfig(
  platform: string,
  providerConfig: Record<string, unknown> | null | undefined,
): string | null {
  const cfg = providerConfig ?? {};
  switch (platform.trim()) {
    case "TikTok":
      return String(cfg.open_id ?? "").trim() || null;
    case "YouTube":
      return String(cfg.channel_id ?? "").trim() || null;
    case "Instagram":
      return String(cfg.instagram_business_account_id ?? "").trim() || null;
    case "LinkedIn":
      return String(cfg.page_id ?? "").trim() || null;
    default:
      return null;
  }
}

export function pickAccountScheduleForModal(
  rows: ScheduleRow[],
  platform: string,
  accountId: string,
): ScheduleRow | null {
  const accountTrim = accountId.trim();
  const filtered = rows
    .filter((s) => {
      if (s.platform !== platform || s.status === "cancelled") return false;
      const rowAccountId =
        String(s.platform_account_id ?? "").trim()
        || getAccountIdFromProviderConfig(platform, s.provider_config);
      return rowAccountId === accountTrim;
    })
    .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at));
  if (!filtered.length) return null;
  return filtered.find((s) => ACTIVE_STATUSES.has(s.status)) ?? filtered[0];
}

export function pickPlatformScheduleForModal(
  rows: ScheduleRow[],
  platform: string,
): ScheduleRow | null {
  const filtered = rows
    .filter((s) => s.platform === platform && s.status !== "cancelled")
    .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at));
  if (!filtered.length) return null;
  return filtered.find((s) => ACTIVE_STATUSES.has(s.status)) ?? filtered[0];
}

import {
  pickAccountScheduleForModal,
  pickPlatformScheduleForModal,
  type ScheduleRow,
} from "./pickPlatformScheduleServer.ts";

export type RequiredPlatformRow = {
  id?: string;
  platform: string;
  is_active?: boolean | null;
  platform_account_id?: string | null;
  platform_account_label?: string | null;
  custom_platform_name?: string | null;
};

export type SocialMediaLinkRow = {
  platform: string;
  url: string | null;
  platform_account_open_id?: string | null;
  created_at?: string | null;
};

export type RequiredPlatformItemStatus =
  | "missing"
  | "scheduled"
  | "publishing"
  | "published"
  | "failed"
  | "link_ready";

export type RequiredPlatformProgressItem = {
  key: string;
  label: string;
  platform: string;
  status: RequiredPlatformItemStatus;
  completedAtIso: string | null;
};

export function filterRequiredPlatformsForContentType(
  required: RequiredPlatformRow[],
  contentTypeName: string | null | undefined,
): RequiredPlatformRow[] {
  const active = required.filter((rp) => rp.is_active !== false);
  const contentType = String(contentTypeName ?? "").trim();
  if (contentType === "Carousel" || contentType === "Post") {
    return active.filter((rp) => rp.platform !== "YouTube" && rp.platform !== "Shopee");
  }
  return active;
}

function isValidLink(link: SocialMediaLinkRow): boolean {
  const url = link.url?.trim() ?? "";
  const platform = link.platform?.trim() ?? "";
  return Boolean(platform && url.startsWith("http"));
}

function requiredPlatformLabel(rp: RequiredPlatformRow): string {
  const base = rp.platform.trim();
  if (rp.platform_account_label?.trim()) return `${base} · ${rp.platform_account_label.trim()}`;
  if (rp.custom_platform_name?.trim()) return `${base} · ${rp.custom_platform_name.trim()}`;
  return base;
}

function findLinkForRequired(
  links: SocialMediaLinkRow[],
  platform: string,
  accountId?: string | null,
): SocialMediaLinkRow | null {
  const platformTrim = platform.trim();
  const valid = links.filter((link) => link.platform?.trim() === platformTrim && isValidLink(link));
  if (!valid.length) return null;

  const accountTrim = accountId?.trim();
  if (accountTrim) {
    const byAccount = valid.find(
      (link) => link.platform_account_open_id?.trim() === accountTrim,
    );
    if (byAccount) return byAccount;
  }

  return valid[0];
}

export function computeRequiredPlatformProgressItems(
  requiredPlatforms: RequiredPlatformRow[],
  links: SocialMediaLinkRow[],
  contentTypeName: string | null | undefined,
  schedules: ScheduleRow[] = [],
): RequiredPlatformProgressItem[] {
  const activeRequired = filterRequiredPlatformsForContentType(requiredPlatforms, contentTypeName);

  return activeRequired.map((rp, index) => {
    const accountId = rp.platform_account_id?.trim() || null;
    const schedule = accountId
      ? pickAccountScheduleForModal(schedules, rp.platform, accountId)
      : pickPlatformScheduleForModal(schedules, rp.platform);
    const link = findLinkForRequired(links, rp.platform, accountId);
    const key = rp.id ?? `${rp.platform}-${accountId ?? index}`;

    let status: RequiredPlatformItemStatus = "missing";
    let completedAtIso: string | null = null;

    if (schedule?.status === "published") {
      status = "published";
      completedAtIso = schedule.published_at ?? schedule.created_at ?? null;
    } else if (schedule?.status === "publishing") {
      status = "publishing";
    } else if (schedule?.status === "pending") {
      status = "scheduled";
    } else if (schedule?.status === "failed") {
      status = "failed";
    } else if (link && isValidLink(link)) {
      status = "link_ready";
      completedAtIso = link.created_at ?? null;
    }

    return {
      key,
      label: requiredPlatformLabel(rp),
      platform: rp.platform,
      status,
      completedAtIso,
    };
  });
}

function isFilledItemStatus(status: RequiredPlatformItemStatus): boolean {
  return status === "published" || status === "link_ready";
}

export function computePlanDoneState(
  requiredPlatforms: RequiredPlatformRow[],
  links: SocialMediaLinkRow[],
  contentTypeName: string | null | undefined,
  schedules: ScheduleRow[] = [],
): boolean {
  const activeRequired = filterRequiredPlatformsForContentType(requiredPlatforms, contentTypeName);

  if (activeRequired.length > 0) {
    const items = computeRequiredPlatformProgressItems(
      requiredPlatforms,
      links,
      contentTypeName,
      schedules,
    );
    return items.length > 0 && items.every((item) => isFilledItemStatus(item.status));
  }

  return links.filter(isValidLink).length >= 1;
}

export const ON_TIME_IN_PROGRESS = "In Progress";
export const ON_TIME_SCHEDULED = "Scheduled";

export function derivePlanPostMetadata(
  items: RequiredPlatformProgressItem[],
  links: SocialMediaLinkRow[],
  postDateIso: string | null,
  hasRequiredPlatforms: boolean,
  calculateOnTimeStatus: (actual: string | null, planned: string | null) => string,
): { actual_post_date: string | null; on_time_status: string } {
  if (!hasRequiredPlatforms) {
    const validLinks = links.filter(isValidLink);
    if (validLinks.length === 0) {
      return { actual_post_date: null, on_time_status: ON_TIME_IN_PROGRESS };
    }
    const dates = validLinks
      .map((l) => l.created_at)
      .filter(Boolean) as string[];
    const earliest = dates.length > 0
      ? dates.sort()[0]
      : new Date().toISOString();
    const actualDate = earliest.split("T")[0];
    return {
      actual_post_date: actualDate,
      on_time_status: calculateOnTimeStatus(actualDate, postDateIso) || ON_TIME_IN_PROGRESS,
    };
  }

  if (items.length === 0) {
    return { actual_post_date: null, on_time_status: ON_TIME_IN_PROGRESS };
  }

  const hasFailed = items.some((item) => item.status === "failed");
  const allComplete = items.every((item) => isFilledItemStatus(item.status));
  const allScheduledOnly = items.every((item) => item.status === "scheduled");

  if (allComplete && !hasFailed) {
    const completionDates = items
      .map((item) => item.completedAtIso)
      .filter(Boolean) as string[];
    const latestIso = completionDates.length > 0
      ? completionDates.sort().at(-1)!
      : new Date().toISOString();
    const actualDate = latestIso.split("T")[0];
    return {
      actual_post_date: actualDate,
      on_time_status: calculateOnTimeStatus(actualDate, postDateIso) || ON_TIME_IN_PROGRESS,
    };
  }

  if (allScheduledOnly) {
    return { actual_post_date: null, on_time_status: ON_TIME_SCHEDULED };
  }

  return { actual_post_date: null, on_time_status: ON_TIME_IN_PROGRESS };
}

export function calculateOnTimeStatus(
  actualPostDateIso: string | null,
  postDateIso: string | null,
): string {
  if (!actualPostDateIso || !postDateIso) return "";
  const actual = new Date(actualPostDateIso);
  const planned = new Date(postDateIso);
  if (Number.isNaN(actual.getTime()) || Number.isNaN(planned.getTime())) return "";
  if (actual <= planned) return "Ontime";
  const diffTime = Math.abs(actual.getTime() - planned.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  return `Late ${diffDays} Day${diffDays > 1 ? "s" : ""}`;
}

export function todayDateIsoUtc(): string {
  return new Date().toISOString().split("T")[0];
}

export function buildPlanPostMetadataUpdates(
  postDateIso: string | null,
  publishedAtIso: string = new Date().toISOString(),
): { actual_post_date: string; on_time_status: string } {
  const actualDate = publishedAtIso.split("T")[0];
  return {
    actual_post_date: actualDate,
    on_time_status: calculateOnTimeStatus(actualDate, postDateIso),
  };
}

