import type { InstagramProviderConfig, ScheduledPostRow } from "./scheduledPostTypes.ts";

const INSTAGRAM_PUBLISH_SCOPES = ["instagram_content_publish"] as const;

function metaScopesIncludePublish(granted: string[]): boolean {
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return INSTAGRAM_PUBLISH_SCOPES.every((s) => grantedSet.has(s.toLowerCase()));
}

type PlanRow = {
  id: string;
  organization_id: string;
  post_date: string | null;
  post_link_created_by: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  content_type?: { name?: string } | null;
};

async function loadPlan(admin: SupabaseClient, planId: string): Promise<PlanRow | null> {
  const { data, error } = await admin
    .from("social_media_plans")
    .select(
      "id, organization_id, post_date, approved, production_approved, google_drive_link, post_link_created_by, content_type:content_types(name)",
    )
    .eq("id", planId)
    .maybeSingle();
  if (error || !data) return null;
  return data as PlanRow;
}

function planEligibilityInput(plan: PlanRow) {
  return {
    post_date: plan.post_date,
    approved: plan.approved,
    production_approved: plan.production_approved,
    google_drive_link: plan.google_drive_link,
    content_type_name: plan.content_type?.name ?? null,
  };
}

async function persistInstagramProviderConfig(
  admin: SupabaseClient,
  scheduleId: string,
  base: Record<string, unknown>,
  patch: Partial<InstagramProviderConfig>,
): Promise<Record<string, unknown>> {
  const next = { ...base, ...patch };
  await admin
    .from("social_media_scheduled_posts")
    .update({ provider_config: next, updated_at: new Date().toISOString() })
    .eq("id", scheduleId);
  return next;
}

async function upsertInstagramLink(
  admin: SupabaseClient,
  plan: PlanRow,
  args: {
    url: string;
    accountId: string;
    accountLabel: string;
    externalPostId: string;
    employeeId?: string;
  },
): Promise<void> {
  const { data: existing } = await admin
    .from("social_media_links")
    .select("id")
    .eq("social_media_plan_id", plan.id)
    .eq("platform", "Instagram")
    .maybeSingle();

  const payload = {
    platform: "Instagram",
    url: args.url,
    social_media_name: args.accountLabel,
    external_post_id: args.externalPostId,
    platform_account_open_id: args.accountId,
    updated_at: new Date().toISOString(),
  };

  if (existing?.id) {
    await admin.from("social_media_links").update(payload).eq("id", existing.id);
  } else {
    await admin.from("social_media_links").insert({ ...payload, social_media_plan_id: plan.id });
    if (!plan.post_link_created_by && args.employeeId) {
      await admin
        .from("social_media_plans")
        .update({ post_link_created_by: args.employeeId })
        .eq("id", plan.id);
    }
  }

  await syncPlanCompletionStateForPlan(admin, plan.id);
}

export async function executeInstagramScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const plan = await loadPlan(admin, schedule.social_media_plan_id);
  if (!plan) throw new Error("plan_not_found");
  if (!isPlanEligibleForInstagramAutoSchedule(planEligibilityInput(plan))) {
    throw new Error("plan_not_eligible");
  }
  if (shouldCancelScheduleDueToDriveMismatch(schedule.media_url_snapshot, plan.google_drive_link)) {
    throw new Error("google_drive_link_changed");
  }

  const cfg = schedule.provider_config as InstagramProviderConfig;
  const igAccountId = String(cfg.instagram_business_account_id ?? "").trim();
  if (!igAccountId) throw new Error("missing_instagram_business_account_id");

  const account = await resolveMetaContentAccount(
    admin,
    schedule.organization_id,
    "instagram",
    igAccountId,
  );
  if (!account?.pageAccessToken) {
    throw new Error("instagram_account_not_found");
  }
  if (!metaScopesIncludePublish(account.grantedScopes)) {
    throw new Error("publish_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };
  const caption = schedule.caption?.trim() || schedule.title?.trim() || "";

  if (cfg.ig_container_id && cfg.ig_upload_phase === "uploaded") {
    const { mediaId } = await publishInstagramReelsContainer(
      igAccountId,
      account.pageAccessToken,
      cfg.ig_container_id,
    );
    const permalink = await fetchInstagramMediaPermalink(mediaId, account.pageAccessToken);
    const publishedUrl = permalink ?? buildInstagramReelsFallbackUrl(mediaId);
    const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Instagram");
    await upsertInstagramLink(admin, plan, {
      url: publishedUrl,
      accountId: igAccountId,
      accountLabel,
      externalPostId: mediaId,
      employeeId: cfg.employee_id,
    });
    return { published_url: publishedUrl, external_post_id: mediaId };
  }

  const driveUrl = plan.google_drive_link?.trim() ?? schedule.media_url_snapshot;
  const { bytes: videoBytes } = await downloadGoogleDriveVideo(driveUrl);

  let containerId = String(cfg.ig_container_id ?? "").trim();
  let uploadUri = "";

  if (!containerId) {
    const container = await createInstagramReelsContainer(
      igAccountId,
      account.pageAccessToken,
      { caption },
    );
    containerId = container.containerId;
    uploadUri = container.uploadUri;
    providerConfig = await persistInstagramProviderConfig(admin, schedule.id, providerConfig, {
      ig_container_id: containerId,
      ig_upload_phase: "created",
    });
  }

  if (cfg.ig_upload_phase !== "uploaded") {
    if (!uploadUri && cfg.ig_upload_session_id) {
      uploadUri = String(cfg.ig_upload_session_id);
    }
    if (!uploadUri) {
      const container = await createInstagramReelsContainer(
        igAccountId,
        account.pageAccessToken,
        { caption },
      );
      containerId = container.containerId;
      uploadUri = container.uploadUri;
      providerConfig = await persistInstagramProviderConfig(admin, schedule.id, providerConfig, {
        ig_container_id: containerId,
        ig_upload_session_id: uploadUri,
        ig_upload_phase: "created",
      });
    }

    await uploadInstagramReelsVideo(uploadUri, account.pageAccessToken, videoBytes);
    providerConfig = await persistInstagramProviderConfig(admin, schedule.id, providerConfig, {
      ig_upload_phase: "uploaded",
    });
  }

  const { mediaId } = await publishInstagramReelsContainer(
    igAccountId,
    account.pageAccessToken,
    containerId,
  );
  const permalink = await fetchInstagramMediaPermalink(mediaId, account.pageAccessToken);
  const publishedUrl = permalink ?? buildInstagramReelsFallbackUrl(mediaId);
  const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Instagram");

  await upsertInstagramLink(admin, plan, {
    url: publishedUrl,
    accountId: igAccountId,
    accountLabel,
    externalPostId: mediaId,
    employeeId: cfg.employee_id,
  });

  return { published_url: publishedUrl, external_post_id: mediaId };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { metaGraphVersion } from "./metaPlatformScopes.ts";

export type MetaContentPlatform = "instagram" | "facebook";

export const metaContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export function metaContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...metaContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: metaContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: metaContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .single();
  if (profile?.active_organization_id !== organizationId) {
    return metaContentJson({ error: "Organization access denied" }, 403);
  }
  return null;
}

export type ResolvedMetaAccount = {
  platform: MetaContentPlatform;
  accountId: string;
  accountLabel: string;
  pageId: string;
  pageAccessToken: string;
  igBusinessAccountId: string | null;
  grantedScopes: string[];
};

function parseScopes(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  return [];
}

export async function resolveMetaContentAccount(
  admin: SupabaseClient,
  organizationId: string,
  platform: MetaContentPlatform,
  accountId: string,
): Promise<ResolvedMetaAccount | null> {
  if (platform === "instagram") {
    const { data } = await admin
      .from("organization_instagram_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("instagram_business_account_id", accountId)
      .eq("is_active", true)
      .maybeSingle();
    if (!data) return null;
    const row = data as Record<string, unknown>;
    const token = String(row.page_access_token ?? "").trim();
    const pageId = String(row.facebook_page_id ?? "").trim();
    if (!token || !pageId) return null;
    return {
      platform: "instagram",
      accountId,
      accountLabel: String(row.instagram_username ?? row.instagram_name ?? accountId),
      pageId,
      pageAccessToken: token,
      igBusinessAccountId: accountId,
      grantedScopes: parseScopes(row.granted_scopes),
    };
  }

  const { data } = await admin
    .from("organization_facebook_pages")
    .select("*")
    .eq("organization_id", organizationId)
    .eq("facebook_page_id", accountId)
    .eq("is_active", true)
    .maybeSingle();
  if (data) {
    const row = data as Record<string, unknown>;
    const token = String(row.page_access_token ?? "").trim();
    if (!token) return null;
    return {
      platform: "facebook",
      accountId,
      accountLabel: String(row.page_name ?? accountId),
      pageId: accountId,
      pageAccessToken: token,
      igBusinessAccountId: null,
      grantedScopes: parseScopes(row.granted_scopes),
    };
  }

  // Page linked to Instagram Business — token lives on organization_instagram_accounts.
  const { data: igLinked } = await admin
    .from("organization_instagram_accounts")
    .select("*")
    .eq("organization_id", organizationId)
    .eq("facebook_page_id", accountId)
    .eq("is_active", true)
    .maybeSingle();
  if (!igLinked) return null;
  const igRow = igLinked as Record<string, unknown>;
  const token = String(igRow.page_access_token ?? "").trim();
  if (!token) return null;
  return {
    platform: "facebook",
    accountId,
    accountLabel: String(
      igRow.facebook_page_name ?? igRow.instagram_username ?? igRow.instagram_name ?? accountId,
    ),
    pageId: accountId,
    pageAccessToken: token,
    igBusinessAccountId: String(igRow.instagram_business_account_id ?? "") || null,
    grantedScopes: parseScopes(igRow.granted_scopes),
  };
}

export async function listMetaContentAccounts(
  admin: SupabaseClient,
  organizationId: string,
): Promise<Array<{
  platform: MetaContentPlatform;
  account_id: string;
  account_label: string;
  page_id: string;
  granted_scopes: string[];
  avatar_url: string | null;
}>> {
  const [igRes, fbRes] = await Promise.all([
    admin
      .from("organization_instagram_accounts")
      .select(
        "instagram_business_account_id, instagram_username, instagram_name, facebook_page_id, facebook_page_name, granted_scopes",
      )
      .eq("organization_id", organizationId)
      .eq("is_active", true),
    admin
      .from("organization_facebook_pages")
      .select("facebook_page_id, page_name, granted_scopes")
      .eq("organization_id", organizationId)
      .eq("is_active", true),
  ]);

  const igAccounts = (igRes.data ?? []).map((row) => {
    const r = row as Record<string, unknown>;
    return {
      platform: "instagram" as const,
      account_id: String(r.instagram_business_account_id),
      account_label: String(r.instagram_username ?? r.instagram_name ?? r.instagram_business_account_id),
      page_id: String(r.facebook_page_id ?? ""),
      granted_scopes: parseScopes(r.granted_scopes),
      avatar_url: null,
    };
  });

  const fbOnlyAccounts = (fbRes.data ?? []).map((row) => {
    const r = row as Record<string, unknown>;
    return {
      platform: "facebook" as const,
      account_id: String(r.facebook_page_id),
      account_label: String(r.page_name ?? r.facebook_page_id),
      page_id: String(r.facebook_page_id),
      granted_scopes: parseScopes(r.granted_scopes),
      avatar_url: null,
    };
  });

  // Pages with linked IG are stored in organization_instagram_accounts but also power Facebook insights/posts.
  const fbFromLinkedIg = (igRes.data ?? [])
    .map((row) => {
      const r = row as Record<string, unknown>;
      const pageId = String(r.facebook_page_id ?? "").trim();
      if (!pageId) return null;
      return {
        platform: "facebook" as const,
        account_id: pageId,
        account_label: String(
          r.facebook_page_name ?? r.instagram_username ?? r.instagram_name ?? pageId,
        ),
        page_id: pageId,
        granted_scopes: parseScopes(r.granted_scopes),
        avatar_url: null,
      };
    })
    .filter((row): row is NonNullable<typeof row> => row != null);

  const fbPageIds = new Set(fbOnlyAccounts.map((a) => a.account_id));
  const fbAccounts = [
    ...fbOnlyAccounts,
    ...fbFromLinkedIg.filter((a) => !fbPageIds.has(a.account_id)),
  ];

  return [...igAccounts, ...fbAccounts];
}

export function graphUrl(path: string, params?: Record<string, string>): string {
  const version = metaGraphVersion();
  const base = `https://graph.facebook.com/${version}/${path}`;
  if (!params || Object.keys(params).length === 0) return base;
  const qs = new URLSearchParams(params);
  return `${base}?${qs.toString()}`;
}

