import {
  isPlanEligibleForFacebookAutoSchedule,
  shouldCancelScheduleDueToDriveMismatch,
} from "./scheduledPostEligibility.ts";
import { syncPlanCompletionStateForPlan } from "./syncPlanCompletionStateDb.ts";
import type { FacebookProviderConfig, ScheduledPostRow } from "./scheduledPostTypes.ts";

type PlanRow = {
  id: string;
  organization_id: string;
  post_date: string | null;
  post_link_created_by: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  content_type?: { name?: string } | null;
};

async function loadPlan(admin: SupabaseClient, planId: string): Promise<PlanRow | null> {
  const { data, error } = await admin
    .from("social_media_plans")
    .select(
      "id, organization_id, post_date, approved, production_approved, google_drive_link, post_link_created_by, content_type:content_types(name)",
    )
    .eq("id", planId)
    .maybeSingle();
  if (error || !data) return null;
  return data as PlanRow;
}

function planEligibilityInput(plan: PlanRow) {
  return {
    post_date: plan.post_date,
    approved: plan.approved,
    production_approved: plan.production_approved,
    google_drive_link: plan.google_drive_link,
    content_type_name: plan.content_type?.name ?? null,
  };
}

async function persistFacebookProviderConfig(
  admin: SupabaseClient,
  scheduleId: string,
  base: Record<string, unknown>,
  patch: Partial<FacebookProviderConfig>,
): Promise<Record<string, unknown>> {
  const next = { ...base, ...patch };
  await admin
    .from("social_media_scheduled_posts")
    .update({ provider_config: next, updated_at: new Date().toISOString() })
    .eq("id", scheduleId);
  return next;
}

async function upsertFacebookLink(
  admin: SupabaseClient,
  plan: PlanRow,
  args: {
    url: string;
    accountId: string;
    accountLabel: string;
    externalPostId: string;
    employeeId?: string;
  },
): Promise<void> {
  const { data: existing } = await admin
    .from("social_media_links")
    .select("id")
    .eq("social_media_plan_id", plan.id)
    .eq("platform", "Facebook")
    .maybeSingle();

  const payload = {
    platform: "Facebook",
    url: args.url,
    social_media_name: args.accountLabel,
    external_post_id: args.externalPostId,
    platform_account_open_id: args.accountId,
    updated_at: new Date().toISOString(),
  };

  if (existing?.id) {
    await admin.from("social_media_links").update(payload).eq("id", existing.id);
  } else {
    await admin.from("social_media_links").insert({ ...payload, social_media_plan_id: plan.id });
    if (!plan.post_link_created_by && args.employeeId) {
      await admin
        .from("social_media_plans")
        .update({ post_link_created_by: args.employeeId })
        .eq("id", plan.id);
    }
  }

  await syncPlanCompletionStateForPlan(admin, plan.id);
}

export async function executeFacebookScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const plan = await loadPlan(admin, schedule.social_media_plan_id);
  if (!plan) throw new Error("plan_not_found");
  if (!isPlanEligibleForFacebookAutoSchedule(planEligibilityInput(plan))) {
    throw new Error("plan_not_eligible");
  }
  if (shouldCancelScheduleDueToDriveMismatch(schedule.media_url_snapshot, plan.google_drive_link)) {
    throw new Error("google_drive_link_changed");
  }

  const cfg = schedule.provider_config as FacebookProviderConfig;
  const pageId = String(cfg.facebook_page_id ?? "").trim();
  if (!pageId) throw new Error("missing_facebook_page_id");

  const account = await resolveMetaContentAccount(
    admin,
    schedule.organization_id,
    "facebook",
    pageId,
  );
  if (!account?.pageAccessToken) {
    throw new Error("facebook_page_not_found");
  }
  if (!facebookPublishScopesOk(account.grantedScopes)) {
    throw new Error("publish_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };
  const caption = schedule.caption?.trim() || schedule.title?.trim() || "";

  let videoId = String(cfg.fb_video_id ?? "").trim();
  let uploadUrl = String(cfg.fb_upload_url ?? "").trim();
  const uploadPhase = String(cfg.fb_upload_phase ?? "").trim();

  if (videoId && uploadPhase === "uploaded") {
    const finished = await finishFacebookReelsPublish(pageId, account.pageAccessToken, {
      videoId,
      description: caption,
    });
    videoId = finished.videoId;
    const permalink = await fetchFacebookReelPermalink(videoId, account.pageAccessToken);
    const publishedUrl = permalink ?? buildFacebookReelFallbackUrl(pageId, videoId);
    const externalPostId = finished.postId ?? videoId;
    const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Facebook");

    await upsertFacebookLink(admin, plan, {
      url: publishedUrl,
      accountId: pageId,
      accountLabel,
      externalPostId,
      employeeId: cfg.employee_id,
    });

    return { published_url: publishedUrl, external_post_id: externalPostId };
  }

  if (!videoId || !uploadUrl) {
    const session = await startFacebookReelsUploadSession(pageId, account.pageAccessToken);
    videoId = session.videoId;
    uploadUrl = session.uploadUrl;
    providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_video_id: videoId,
      fb_upload_url: uploadUrl,
      fb_upload_phase: "started",
    });
  }

  if (uploadPhase !== "uploaded") {
    const driveUrl = plan.google_drive_link?.trim() ?? schedule.media_url_snapshot;
    const { bytes: videoBytes } = await downloadGoogleDriveVideo(driveUrl);
    await uploadFacebookReelsVideo(uploadUrl, account.pageAccessToken, videoBytes);
    providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_upload_phase: "uploaded",
    });
  }

  const finished = await finishFacebookReelsPublish(pageId, account.pageAccessToken, {
    videoId,
    description: caption,
  });
  videoId = finished.videoId;
  const permalink = await fetchFacebookReelPermalink(videoId, account.pageAccessToken);
  const publishedUrl = permalink ?? buildFacebookReelFallbackUrl(pageId, videoId);
  const externalPostId = finished.postId ?? videoId;
  const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Facebook");

  await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
    fb_upload_phase: "published",
  });

  await upsertFacebookLink(admin, plan, {
    url: publishedUrl,
    accountId: pageId,
    accountLabel,
    externalPostId,
    employeeId: cfg.employee_id,
  });

  return { published_url: publishedUrl, external_post_id: externalPostId };
}

import { graphUrl } from "../metaContentAuth.ts";

export type FacebookReelsStartResult = {
  videoId: string;
  uploadUrl: string;
};

export type FacebookReelsFinishResult = {
  videoId: string;
  postId: string | null;
};

function parseGraphError(json: unknown, fallback: string): string {
  const err = (json as { error?: { message?: string } })?.error?.message;
  return err?.trim() || fallback;
}

export async function startFacebookReelsUploadSession(
  pageId: string,
  pageAccessToken: string,
): Promise<FacebookReelsStartResult> {
  const url = graphUrl(`${pageId}/video_reels`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      upload_phase: "start",
    }),
  });

  const json = await res.json().catch(() => ({})) as {
    video_id?: string;
    upload_url?: string;
    error?: { message?: string };
  };

  if (!res.ok || !json.video_id) {
    throw new Error(
      `meta_fb_reels_start HTTP ${res.status}: ${parseGraphError(json, "unknown")}`,
    );
  }

  const uploadUrl = String(json.upload_url ?? "").trim();
  if (!uploadUrl) throw new Error("meta_fb_reels_missing_upload_url");

  return { videoId: String(json.video_id), uploadUrl };
}

export async function uploadFacebookReelsVideo(
  uploadUrl: string,
  pageAccessToken: string,
  videoBytes: Uint8Array,
): Promise<void> {
  const res = await fetch(uploadUrl, {
    method: "POST",
    headers: {
      Authorization: `OAuth ${pageAccessToken}`,
      "Content-Type": "application/octet-stream",
      offset: "0",
      file_size: String(videoBytes.byteLength),
    },
    body: videoBytes,
  });

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`meta_fb_reels_upload HTTP ${res.status}: ${text.slice(0, 300)}`);
  }
}

export async function finishFacebookReelsPublish(
  pageId: string,
  pageAccessToken: string,
  args: { videoId: string; description: string },
): Promise<FacebookReelsFinishResult> {
  const url = graphUrl(`${pageId}/video_reels`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      upload_phase: "finish",
      video_id: args.videoId,
      video_state: "PUBLISHED",
      description: args.description.slice(0, 2200),
    }),
  });

  const json = await res.json().catch(() => ({})) as {
    video_id?: string;
    post_id?: string;
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (!res.ok || json.success === false) {
    const msg = parseGraphError(json, "unknown");
    if (msg.toLowerCase().includes("limit") || json.error?.code === 368) {
      throw new Error(`meta_fb_reels_rate_limit: ${msg}`);
    }
    throw new Error(`meta_fb_reels_finish HTTP ${res.status}: ${msg}`);
  }

  return {
    videoId: String(json.video_id ?? args.videoId),
    postId: json.post_id ? String(json.post_id) : null,
  };
}

export async function fetchFacebookReelPermalink(
  videoId: string,
  pageAccessToken: string,
): Promise<string | null> {
  const url = graphUrl(videoId, { fields: "permalink_url,permalink" });
  const res = await fetch(`${url}&access_token=${encodeURIComponent(pageAccessToken)}`);
  const json = await res.json().catch(() => ({})) as {
    permalink_url?: string;
    permalink?: string;
  };
  return json.permalink_url?.trim() || json.permalink?.trim() || null;
}

export function buildFacebookReelFallbackUrl(pageId: string, videoId: string): string {
  return `https://www.facebook.com/${encodeURIComponent(pageId)}/videos/${encodeURIComponent(videoId)}/`;
}

export async function deleteFacebookReelVideo(
  videoId: string,
  pageAccessToken: string,
): Promise<{ ok: boolean; alreadyDeleted: boolean; error?: string }> {
  const url = graphUrl(videoId);
  const res = await fetch(`${url}?access_token=${encodeURIComponent(pageAccessToken)}`, {
    method: "DELETE",
  });
  const json = await res.json().catch(() => ({})) as {
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (res.ok && json.success !== false) {
    return { ok: true, alreadyDeleted: false };
  }

  const code = json.error?.code;
  const msg = json.error?.message ?? "";
  if (code === 100 || msg.toLowerCase().includes("not exist")) {
    return { ok: true, alreadyDeleted: true };
  }

  return { ok: false, alreadyDeleted: false, error: msg || `http_${res.status}` };
}

export async function deleteInstagramMedia(
  mediaId: string,
  pageAccessToken: string,
): Promise<{ ok: boolean; alreadyDeleted: boolean; error?: string }> {
  const url = graphUrl(mediaId);
  const res = await fetch(`${url}?access_token=${encodeURIComponent(pageAccessToken)}`, {
    method: "DELETE",
  });
  const json = await res.json().catch(() => ({})) as {
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (res.ok && json.success !== false) {
    return { ok: true, alreadyDeleted: false };
  }

  const code = json.error?.code;
  const msg = json.error?.message ?? "";
  if (code === 100 || msg.toLowerCase().includes("not exist")) {
    return { ok: true, alreadyDeleted: true };
  }

  return { ok: false, alreadyDeleted: false, error: msg || `http_${res.status}` };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  parseYouTubeOAuthScopes,
  youtubeContentScopesIncludeUpload,
} from "../youtubeContentAuth.ts";
import { getYouTubeContentAccessToken } from "../youtubeContentOrgResolver.ts";
import {
  appendShortsHashtag,
  assertYouTubeVideoOwnedByChannel,
  buildYouTubePublishedUrl,
  computeYouTubeUploadChunkPlan,
  initYouTubeResumableUpload,
  mapSchedulePrivacyToYouTube,
  pollYouTubeVideoUntilProcessed,
  uploadYouTubeVideoChunks,
} from "../youtubeContent/youtubeContentPublishApi.ts";
import { downloadGoogleDriveVideo } from "./googleDriveVideoDownload.ts";
import {
  isPlanEligibleForYouTubeAutoSchedule,
  isReelContentType,
  shouldCancelScheduleDueToDriveMismatch,
} from "./scheduledPostEligibility.ts";
import { syncPlanCompletionStateForPlan } from "./syncPlanCompletionStateDb.ts";
import type { ScheduledPostRow, YouTubeProviderConfig } from "./scheduledPostTypes.ts";
import { DEFAULT_YOUTUBE_SCHEDULE_PRIVACY } from "./normalizeYouTubeSchedulePrivacy.ts";

type PlanRow = {
  id: string;
  organization_id: string;
  post_date: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  post_link_created_by: string | null;
  content_type?: { name?: string } | null;
};

async function loadPlan(admin: SupabaseClient, planId: string): Promise<PlanRow | null> {
  const { data, error } = await admin
    .from("social_media_plans")
    .select(
      "id, organization_id, post_date, approved, production_approved, google_drive_link, post_link_created_by, content_type:content_types(name)",
    )
    .eq("id", planId)
    .maybeSingle();
  if (error || !data) return null;
  return data as PlanRow;
}

function planEligibilityInput(plan: PlanRow) {
  return {
    post_date: plan.post_date,
    approved: plan.approved,
    production_approved: plan.production_approved,
    google_drive_link: plan.google_drive_link,
    content_type_name: plan.content_type?.name ?? null,
  };
}

async function persistYouTubeProviderConfig(
  admin: SupabaseClient,
  scheduleId: string,
  base: Record<string, unknown>,
  patch: Partial<YouTubeProviderConfig>,
): Promise<Record<string, unknown>> {
  const next = { ...base, ...patch };
  await admin
    .from("social_media_scheduled_posts")
    .update({
      provider_config: next,
      updated_at: new Date().toISOString(),
    })
    .eq("id", scheduleId);
  return next;
}

async function upsertYouTubeLink(
  admin: SupabaseClient,
  plan: PlanRow,
  args: {
    url: string;
    channelId: string;
    accountLabel: string;
    externalPostId: string;
    employeeId?: string;
  },
): Promise<void> {
  const { data: existing } = await admin
    .from("social_media_links")
    .select("id")
    .eq("social_media_plan_id", plan.id)
    .eq("platform", "YouTube")
    .maybeSingle();

  const payload = {
    platform: "YouTube",
    url: args.url,
    social_media_name: args.accountLabel,
    external_post_id: args.externalPostId,
    platform_account_open_id: args.channelId,
    updated_at: new Date().toISOString(),
  };

  if (existing?.id) {
    await admin.from("social_media_links").update(payload).eq("id", existing.id);
  } else {
    await admin.from("social_media_links").insert({
      ...payload,
      social_media_plan_id: plan.id,
    });

    if (!plan.post_link_created_by) {
      const employeeId = String(args.employeeId ?? "").trim();
      if (employeeId) {
        await admin
          .from("social_media_plans")
          .update({ post_link_created_by: employeeId })
          .eq("id", plan.id);
      }
    }
  }

  await syncPlanCompletionStateForPlan(admin, plan.id);
}

async function finalizeYouTubePublish(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
  plan: PlanRow,
  channelId: string,
  videoId: string,
  cfg: YouTubeProviderConfig,
  verified?: { channelTitle?: string; privacyStatus?: string | null },
): Promise<{ published_url: string; external_post_id: string }> {
  const { data: account } = await admin
    .from("organization_youtube_content_accounts")
    .select("label, display_name")
    .eq("organization_id", schedule.organization_id)
    .eq("channel_id", channelId)
    .maybeSingle();

  const accountLabel = String(
    cfg.account_label ?? account?.display_name ?? account?.label ?? "YouTube",
  );
  const publishedUrl = buildYouTubePublishedUrl(videoId);

  await upsertYouTubeLink(admin, plan, {
    url: publishedUrl,
    channelId,
    accountLabel,
    externalPostId: videoId,
    employeeId: cfg.employee_id,
  });

  if (verified?.channelTitle || verified?.privacyStatus) {
    await persistYouTubeProviderConfig(
      admin,
      schedule.id,
      schedule.provider_config as Record<string, unknown>,
      {
        published_channel_id: channelId,
        ...(verified.channelTitle ? { published_channel_title: verified.channelTitle } : {}),
        ...(verified.privacyStatus ? { published_privacy_status: verified.privacyStatus } : {}),
      },
    );
  }

  return { published_url: publishedUrl, external_post_id: videoId };
}

export async function executeYouTubeScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const plan = await loadPlan(admin, schedule.social_media_plan_id);
  if (!plan) throw new Error("plan_not_found");

  if (!isPlanEligibleForYouTubeAutoSchedule(planEligibilityInput(plan))) {
    throw new Error("plan_not_eligible");
  }

  if (shouldCancelScheduleDueToDriveMismatch(schedule.media_url_snapshot, plan.google_drive_link)) {
    throw new Error("google_drive_link_changed");
  }

  const cfg = schedule.provider_config as YouTubeProviderConfig;
  const channelId = String(cfg.channel_id ?? "").trim();
  if (!channelId) throw new Error("missing_channel_id");

  const accessToken = await getYouTubeContentAccessToken(
    admin,
    schedule.organization_id,
    channelId,
  );
  if (!accessToken) {
    throw new Error("youtube_token_missing: Re-authorize YouTube in Digital Marketing settings");
  }

  const { data: tokenRow } = await admin
    .from("organization_youtube_content_connection_tokens")
    .select("oauth_scopes")
    .eq("organization_id", schedule.organization_id)
    .eq("channel_id", channelId)
    .maybeSingle();

  const scopes = parseYouTubeOAuthScopes(tokenRow?.oauth_scopes);
  if (!youtubeContentScopesIncludeUpload(scopes)) {
    throw new Error("upload_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };

  if (cfg.youtube_video_id) {
    const verified = await assertYouTubeVideoOwnedByChannel(
      accessToken,
      cfg.youtube_video_id,
      channelId,
    );
    await pollYouTubeVideoUntilProcessed(accessToken, cfg.youtube_video_id);
    return finalizeYouTubePublish(
      admin,
      schedule,
      plan,
      channelId,
      cfg.youtube_video_id,
      cfg,
      verified,
    );
  }

  const title = schedule.title?.trim() || plan.content_type?.name?.trim() || "Synckerja Reel";
  const isReel = isReelContentType(plan.content_type?.name);
  const description = appendShortsHashtag(
    schedule.caption?.trim() || schedule.title?.trim() || "",
    isReel,
  );
  const privacyStatus = mapSchedulePrivacyToYouTube(
    schedule.privacy_level ?? DEFAULT_YOUTUBE_SCHEDULE_PRIVACY,
  );

  const driveUrl = plan.google_drive_link?.trim() ?? schedule.media_url_snapshot;
  const { bytes: videoBytes, mimeType } = await downloadGoogleDriveVideo(driveUrl);
  const chunkPlan = computeYouTubeUploadChunkPlan(videoBytes.byteLength);

  let uploadUrl = String(cfg.youtube_upload_url ?? "").trim();
  let startByte = Number(cfg.youtube_upload_bytes_sent ?? 0);

  if (!uploadUrl) {
    const init = await initYouTubeResumableUpload(accessToken, {
      title,
      description,
      privacyStatus,
      videoSize: videoBytes.byteLength,
      mimeType,
    });
    uploadUrl = init.uploadUrl;
    startByte = 0;
    providerConfig = await persistYouTubeProviderConfig(admin, schedule.id, providerConfig, {
      youtube_upload_url: uploadUrl,
      youtube_upload_bytes_sent: 0,
      youtube_upload_completed: false,
    });
  }

  const { videoId } = await uploadYouTubeVideoChunks(
    uploadUrl,
    accessToken,
    videoBytes,
    chunkPlan,
    mimeType,
    startByte,
  );

  providerConfig = await persistYouTubeProviderConfig(admin, schedule.id, providerConfig, {
    youtube_upload_completed: true,
    youtube_upload_bytes_sent: videoBytes.byteLength,
    youtube_video_id: videoId,
  });

  const verified = await assertYouTubeVideoOwnedByChannel(accessToken, videoId, channelId);
  await pollYouTubeVideoUntilProcessed(accessToken, videoId);

  return finalizeYouTubePublish(admin, schedule, plan, channelId, videoId, cfg, verified);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const youtubeContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const YOUTUBE_CONTENT_COMMENTS_OAUTH_SCOPE =
  "https://www.googleapis.com/auth/youtube.force-ssl";

export const YOUTUBE_CONTENT_UPLOAD_OAUTH_SCOPE =
  "https://www.googleapis.com/auth/youtube.upload";

export const YOUTUBE_CONTENT_OAUTH_SCOPES = [
  "https://www.googleapis.com/auth/youtube.readonly",
  YOUTUBE_CONTENT_UPLOAD_OAUTH_SCOPE,
  YOUTUBE_CONTENT_COMMENTS_OAUTH_SCOPE,
  "https://www.googleapis.com/auth/yt-analytics.readonly",
].join(" ");

export function parseYouTubeOAuthScopes(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  if (typeof raw === "string") {
    return raw.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
  }
  return [];
}

export function youtubeContentScopesIncludeUpload(scopes: unknown): boolean {
  const list = parseYouTubeOAuthScopes(scopes);
  return list.some(
    (s) =>
      s.includes("youtube.upload")
      || s === "https://www.googleapis.com/auth/youtube",
  );
}

export function hasYouTubeCommentsOAuthScope(scopes: string[]): boolean {
  return scopes.some(
    (s) =>
      s.includes("youtube.force-ssl")
      || s === "https://www.googleapis.com/auth/youtube",
  );
}

export function youtubeContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...youtubeContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformYouTubeContentOAuth(): { clientId: string; clientSecret: string } | null {
  const clientId = Deno.env.get("YOUTUBE_CONTENT_CLIENT_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("YOUTUBE_CONTENT_CLIENT_SECRET")?.trim() ?? "";
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

export function isYouTubeContentPlatformConfigured(): boolean {
  return readPlatformYouTubeContentOAuth() !== null;
}

export function requireYouTubeContentPlatformConfigured(): Response | null {
  if (!isYouTubeContentPlatformConfigured()) {
    return youtubeContentJson(
      {
        error:
          "YouTube Content is not configured. Set YOUTUBE_CONTENT_CLIENT_ID and YOUTUBE_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function youtubeContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("YOUTUBE_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/youtube-content-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const YOUTUBE_CONTENT_OAUTH_RETURN_PATHS = new Set([
