export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: youtubeContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: youtubeContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelContentAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelContentAdmin(admin, userId, organizationId);
  if (!ok) return youtubeContentJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return youtubeContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptYouTubeContentToken,
  encryptYouTubeContentToken,
} from "./youtubeContentConfigCrypto.ts";
import { readPlatformYouTubeContentOAuth } from "./youtubeContentAuth.ts";
import { refreshYouTubeContentAccessToken } from "./youtubeContentApi.ts";

export type YouTubeContentAccountRow = {
  id: string;
  organization_id: string;
  channel_id: string;
  label: string;
  display_name: string | null;
  thumbnail_url: string | null;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
};

export async function getYouTubeContentAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  channelId: string,
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_youtube_content_connection_tokens")
    .select("access_token_enc, refresh_token_enc, access_token_expires_at")
    .eq("organization_id", organizationId)
    .eq("channel_id", channelId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000;

  if (!needsRefresh) {
    try {
      return await decryptYouTubeContentToken(String(tokenRow.access_token_enc));
    } catch (e) {
      console.error("getYouTubeContentAccessToken decrypt:", e);
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptYouTubeContentToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getYouTubeContentAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformYouTubeContentOAuth();
  const refreshed = oauth
    ? await refreshYouTubeContentAccessToken(oauth.clientId, oauth.clientSecret, refreshToken)
    : null;

  if (!refreshed?.access_token) {
    try {
      return await decryptYouTubeContentToken(String(tokenRow.access_token_enc));
    } catch {
      return null;
    }
  }

  const now = new Date().toISOString();
  const accessEnc = await encryptYouTubeContentToken(refreshed.access_token);
  const refreshEnc = refreshed.refresh_token
    ? await encryptYouTubeContentToken(refreshed.refresh_token)
    : String(tokenRow.refresh_token_enc);
  const accessExpires = refreshed.expires_in
    ? new Date(Date.now() + refreshed.expires_in * 1000).toISOString()
    : tokenRow.access_token_expires_at;

  await admin.from("organization_youtube_content_connection_tokens").update({
    access_token_enc: accessEnc,
    refresh_token_enc: refreshEnc,
    access_token_expires_at: accessExpires,
    updated_at: now,
  }).eq("organization_id", organizationId).eq("channel_id", channelId);

  return refreshed.access_token;
}

export async function resolveOrgYouTubeContentForMetrics(
  admin: SupabaseClient,
  organizationId: string,
  channelIdParam?: string | null,
): Promise<{ accessToken: string; account: YouTubeContentAccountRow } | null> {
  let account: YouTubeContentAccountRow | null = null;

  if (channelIdParam) {
    const { data: row } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("channel_id", channelIdParam.trim())
      .maybeSingle();
    if (row) account = row as YouTubeContentAccountRow;
  }

  if (!account) {
    const { data: defaultRow } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .eq("is_default", true)
      .maybeSingle();
    account = (defaultRow as YouTubeContentAccountRow | null) ?? null;
  }

  if (!account) {
    const { data: firstRow } = await admin
      .from("organization_youtube_content_accounts")
      .select("*")
      .eq("organization_id", organizationId)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })
      .limit(1)
      .maybeSingle();
    account = (firstRow as YouTubeContentAccountRow | null) ?? null;
  }

  if (!account?.channel_id) return null;

  const accessToken = await getYouTubeContentAccessToken(admin, organizationId, account.channel_id);
  if (!accessToken) return null;

  return { accessToken, account };
}

/**
 * AES-256-GCM for YouTube Content OAuth tokens.
 * Key: YOUTUBE_CONTENT_CONFIG_ENCRYPTION_KEY (or GOOGLE_ADS_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("YOUTUBE_CONTENT_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("GOOGLE_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptYouTubeContentToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptYouTubeContentToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}

const YOUTUBE_DATA_API = "https://www.googleapis.com/youtube/v3";
const YOUTUBE_ANALYTICS_API = "https://youtubeanalytics.googleapis.com/v2";
const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";

export type YouTubeChannelRow = {
  channel_id: string;
  title: string;
  thumbnail_url: string | null;
  uploads_playlist_id: string | null;
};

export type YouTubeVideoPrivacyStatus = "public" | "unlisted" | "private";

export type YouTubeVideoRow = {
  id?: string;
  title?: string;
  published_at?: string;
  thumbnail_url?: string | null;
  privacy_status?: YouTubeVideoPrivacyStatus | null;
  view_count?: number;
  like_count?: number;
  comment_count?: number;
  share_count?: number;
  subscribers_gained?: number;
};

type GoogleTokenResponse = {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  error?: string;
  error_description?: string;
};

function throwGoogleError(prefix: string, json: GoogleTokenResponse, httpStatus: number): never {
  const msg = json.error_description?.trim() || json.error?.trim() || `${prefix} HTTP ${httpStatus}`;
  throw new Error(msg);
}

export async function exchangeYouTubeContentAuthCode(
  clientId: string,
  clientSecret: string,
  code: string,
  redirectUri: string,
  codeVerifier: string,
): Promise<{
  access_token: string;
  refresh_token: string;
  expires_in?: number;
}> {
  const body = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    code: decodeURIComponent(code),
    grant_type: "authorization_code",
    redirect_uri: redirectUri,
    code_verifier: codeVerifier,
  });
  const res = await fetch(GOOGLE_TOKEN_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });
  const json = await res.json().catch(() => ({})) as GoogleTokenResponse;
  const accessToken = json.access_token?.trim() ?? "";
  const refreshToken = json.refresh_token?.trim() ?? "";
  if (!res.ok || !accessToken) {
    throwGoogleError("token_exchange_failed", json, res.status);
  }
  return {
    access_token: accessToken,
    refresh_token: refreshToken || accessToken,
    expires_in: json.expires_in,
  };
}

export async function refreshYouTubeContentAccessToken(
  clientId: string,
  clientSecret: string,
  refreshToken: string,
): Promise<{
  access_token: string;
  refresh_token?: string;
  expires_in?: number;
} | null> {
  const body = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: "refresh_token",
    refresh_token: refreshToken,
  });
  const res = await fetch(GOOGLE_TOKEN_URL, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });
  const json = await res.json().catch(() => ({})) as GoogleTokenResponse;
  const accessToken = json.access_token?.trim() ?? "";
  if (!res.ok || !accessToken) {
    console.error("youtube content refresh:", json.error_description ?? json.error ?? res.status);
    return null;
  }
  return {
    access_token: accessToken,
    refresh_token: json.refresh_token,
    expires_in: json.expires_in,
  };
}

type YouTubeApiError = {
  error?: {
    message?: string;
    code?: number;
    errors?: Array<{ reason?: string; message?: string }>;
  };
};

async function youtubeDataGet<T>(
  accessToken: string,
  path: string,
  params: Record<string, string>,
): Promise<T> {
  const qs = new URLSearchParams(params);
  const res = await fetch(`${YOUTUBE_DATA_API}${path}?${qs.toString()}`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });
  const json = await res.json().catch(() => ({})) as T & YouTubeApiError;
  if (!res.ok) {
    const msg = json.error?.message ?? `YouTube API HTTP ${res.status}`;
    const reason = json.error?.errors?.[0]?.reason;
    const detail = reason ? `${msg} (${reason})` : msg;
    throw new Error(`YouTube ${path} HTTP ${res.status}: ${detail}`);
  }
  return json;
}

async function youtubeDataPost<T>(
  accessToken: string,
  path: string,
  params: Record<string, string>,
  body: object,
): Promise<T> {
  const qs = new URLSearchParams(params);
  const res = await fetch(`${YOUTUBE_DATA_API}${path}?${qs.toString()}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({})) as T & YouTubeApiError;
  if (!res.ok) {
    const msg = json.error?.message ?? `YouTube API HTTP ${res.status}`;
    const reason = json.error?.errors?.[0]?.reason;
    const detail = reason ? `${msg} (${reason})` : msg;
    throw new Error(`YouTube ${path} HTTP ${res.status}: ${detail}`);
  }
  return json;
}

export async function fetchYouTubeChannelsMine(accessToken: string): Promise<YouTubeChannelRow[]> {
  const json = await youtubeDataGet<{
    items?: Array<{
      id?: string;
      snippet?: { title?: string; thumbnails?: { default?: { url?: string }; medium?: { url?: string } } };
      contentDetails?: { relatedPlaylists?: { uploads?: string } };
    }>;
  }>(accessToken, "/channels", {
    part: "snippet,contentDetails",
    mine: "true",
    maxResults: "50",
  });

  return (json.items ?? []).map((item) => {
    const channelId = String(item.id ?? "").trim();
    const thumbs = item.snippet?.thumbnails;
    const thumb = thumbs?.medium?.url ?? thumbs?.default?.url ?? null;
    return {
      channel_id: channelId,
      title: String(item.snippet?.title ?? "").trim() || channelId,
      thumbnail_url: thumb,
      uploads_playlist_id: item.contentDetails?.relatedPlaylists?.uploads ?? null,
    };
  }).filter((c) => c.channel_id);
}

