import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  INTERNAL_DEFER_JITTER_SECONDS,
  INTERNAL_DEFER_SECONDS,
  type RateLimitDeferReason,
} from "./rateLimitConfig.ts";
import {
  isInstagramResumeRow,
  isLinkedInResumeRow,
  isPublishResumeRow,
  isTikTokResumeRow,
  isYouTubeResumeRow,
  stripPublishResumeFlags,
} from "./publishResume.ts";

function computeDeferAt(): string {
  const jitter = Math.floor(Math.random() * (INTERNAL_DEFER_JITTER_SECONDS * 2 + 1))
    - INTERNAL_DEFER_JITTER_SECONDS;
  const seconds = Math.max(30, INTERNAL_DEFER_SECONDS + jitter);
  return new Date(Date.now() + seconds * 1000).toISOString();
}

export async function deferForRateLimit(
  admin: SupabaseClient,
  scheduleId: string,
  reason: RateLimitDeferReason,
): Promise<string> {
  const nextRetryAt = computeDeferAt();
  const now = new Date().toISOString();

  const { error } = await admin
    .from("social_media_scheduled_posts")
    .update({
      status: "pending",
      locked_at: null,
      next_retry_at: nextRetryAt,
      error_message: reason,
      updated_at: now,
    })
    .eq("id", scheduleId)
    .eq("status", "publishing");

  if (error) throw new Error(error.message);
  return nextRetryAt;
}

export {
  isInstagramResumeRow,
  isLinkedInResumeRow,
  isPublishResumeRow,
  isTikTokResumeRow,
  isYouTubeResumeRow,
  stripPublishResumeFlags,
};

function isTruthyFlag(value: unknown): boolean {
  return value === true || value === "true";
}

export function isTikTokResumeRow(providerConfig: Record<string, unknown>): boolean {
  return (
    typeof providerConfig.tiktok_publish_id === "string" &&
    providerConfig.tiktok_publish_id.length > 0 &&
    isTruthyFlag(providerConfig.tiktok_upload_completed)
  );
}

export function isYouTubeResumeRow(providerConfig: Record<string, unknown>): boolean {
  const videoId = providerConfig.youtube_video_id;
  if (typeof videoId === "string" && videoId.length > 0) {
    return true;
  }
  const uploadUrl = providerConfig.youtube_upload_url;
  return typeof uploadUrl === "string" && uploadUrl.length > 0;
}

export function isInstagramResumeRow(providerConfig: Record<string, unknown>): boolean {
  const containerId = providerConfig.ig_container_id;
  return typeof containerId === "string" && containerId.length > 0;
}

export function isLinkedInResumeRow(providerConfig: Record<string, unknown>): boolean {
  const uploadUrn = providerConfig.linkedin_upload_urn;
  const postUrn = providerConfig.linkedin_post_urn;
  return (
    (typeof uploadUrn === "string" && uploadUrn.length > 0) ||
    (typeof postUrn === "string" && postUrn.length > 0)
  );
}

export function isFacebookResumeRow(providerConfig: Record<string, unknown>): boolean {
  const videoId = providerConfig.fb_video_id;
  return typeof videoId === "string" && videoId.length > 0;
}

export function isPublishResumeRow(
  platform: string,
  providerConfig: Record<string, unknown>,
): boolean {
  switch (platform.trim()) {
    case "TikTok":
      return isTikTokResumeRow(providerConfig);
    case "YouTube":
      return isYouTubeResumeRow(providerConfig);
    case "Instagram":
      return isInstagramResumeRow(providerConfig);
    case "Facebook":
      return isFacebookResumeRow(providerConfig);
    case "LinkedIn":
      return isLinkedInResumeRow(providerConfig);
    default:
      return false;
  }
}

export function stripPublishResumeFlags(
  platform: string,
  providerConfig: Record<string, unknown>,
): Record<string, unknown> {
  const next = { ...providerConfig };
  switch (platform.trim()) {
    case "TikTok":
      delete next.tiktok_publish_id;
      delete next.tiktok_upload_completed;
      break;
    case "YouTube":
      delete next.youtube_upload_url;
      delete next.youtube_upload_bytes_sent;
      delete next.youtube_upload_completed;
      delete next.youtube_video_id;
      break;
    case "Instagram":
      delete next.ig_container_id;
      delete next.ig_upload_phase;
      delete next.ig_upload_session_id;
      break;
    case "Facebook":
      delete next.fb_video_id;
      delete next.fb_upload_url;
      delete next.fb_upload_phase;
      break;
    case "LinkedIn":
      delete next.linkedin_upload_urn;
      delete next.linkedin_upload_instructions;
      delete next.linkedin_post_urn;
      break;
    default:
      break;
  }
  return next;
}

export const scheduledPostsCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export function scheduledPostsJson(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...scheduledPostsCorsHeaders, "Content-Type": "application/json" },
  });
}

/** Service role JWT or SCHEDULED_POSTS_INTERNAL_SECRET (pg_cron). */
export function isScheduledPostsInternalAuthorized(req: Request): boolean {
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const cronSecret = Deno.env.get("SCHEDULED_POSTS_INTERNAL_SECRET") ?? "";
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.startsWith("Bearer ") ? authHeader.slice(7).trim() : "";
  return token === serviceRoleKey || (cronSecret.length > 0 && token === cronSecret);
}
